  'Task': 'Tarea',
  'The task is on the date found. {summary} is the line it was in without the date, {line} the whole line, {time} its time (tasks have no time of their own, so it goes into the text), {title} the note\'s title': 'La tarea va en la fecha encontrada. {summary} es la línea en la que estaba sin la fecha, {line} la línea completa, {time} su hora (las tareas no tienen hora propia, así que va en el texto), {title} el título de la nota',
