  'Improve the title with the language model': 'Mejorar el título con el modelo de lenguaje',
  'Rewrites {summary} when the model from Settings is installed; otherwise it stays as it is': 'Reescribe {summary} cuando el modelo de los ajustes está instalado; si no, se queda como está',
  'Due: {when}': 'Vence: {when}',
  'Reads the pen writing of each page in the background and puts the text in a box under it. A page is read again only when its writing changes. Needs the handwriting model from Settings; a page takes a while on a tablet.': 'Lee la escritura a mano de cada página en segundo plano y pone el texto en un cuadro debajo. Una página se vuelve a leer solo cuando cambia su escritura. Necesita el modelo de escritura a mano de los ajustes; en una tableta una página tarda un poco.',
  'A language model on this device reads the note and compares it with the notes in each folder; the note goes to the folder it resembles most, if that is clear enough. Needs the sentence model from Settings. The notes of a folder are read once, and again only when they change.': 'Un modelo de lenguaje de este dispositivo lee la nota y la compara con las notas de cada carpeta; la nota va a la carpeta a la que más se parece, si está lo bastante claro. Necesita el modelo de frases de los ajustes. Las notas de una carpeta se leen una vez, y de nuevo solo cuando cambian.',
