  'Leave': 'Salir',
  'Start a live session and send the link to whoever should join. Everything that is drawn or written shows up for everyone at once. What is sent is sealed with a key that only the link contains: nobody in between (not even the server that introduces your devices to each other) can read it. The session lasts as long as you keep this note open and the app running.': 'Inicia una sesión en vivo y envía el enlace a quien deba unirse. Todo lo que se dibuja o escribe aparece para todos a la vez. Lo que se envía va sellado con una clave que solo contiene el enlace: nadie en medio (ni siquiera el servidor que presenta tus dispositivos entre sí) puede leerlo. La sesión dura mientras tengas esta nota abierta y la aplicación en marcha.',
