  'Advanced: server and relay': 'Avanzado: servidor y relé',
  'Platform look': 'Aspecto de la plataforma',
  'Automatic dresses the app like an iPhone app on an iPhone or iPad, and like a Material app elsewhere. Pick one to see it on any device.': 'Automático da a la aplicación el aspecto de una app de iPhone en iPhone o iPad, y el de una app Material en los demás casos. Elige uno para verlo en cualquier dispositivo.',
  'Material': 'Material',
  'Colors the buttons, selections and markers in every part of the app.': 'Colorea los botones, las selecciones y los marcadores en todas las partes de la aplicación.',
  'Button': 'Botón',
  'Chip': 'Chip',
  'Language model': 'Modelo de lenguaje',
  'Titles for tasks from PDFs': 'Títulos de tareas de PDF',
  'Record a meeting on the dashboard, or dictate into a note, and what is said is written down. It happens on this device (Whisper, MIT and Apache-2.0 licences); the sound is never sent away and not kept.': 'Graba una reunión desde el panel o dicta en una nota, y lo que se dice queda escrito. Ocurre en este dispositivo (Whisper, licencias MIT y Apache-2.0); el sonido nunca se envía a ningún sitio ni se guarda.',
  'Writes short titles for the tasks that automations make from dates in a PDF (Qwen3-0.6B, Apache-2.0 licence). It runs on this device and nothing is sent away; it is loaded only while it works. It needs a fair amount of memory while it does.': 'Escribe títulos cortos para las tareas que crean las automatizaciones a partir de fechas de un PDF (Qwen3-0.6B, licencia Apache-2.0). Se ejecuta en este dispositivo y no se envía nada fuera; solo se carga mientras trabaja, y mientras trabaja necesita bastante memoria.',
  'Colors, borders and emoji for the calendar itself are set in the Calendar tab, with the palette button at the top.': 'Los colores, bordes y emojis del propio calendario se configuran en la pestaña Calendario, con el botón de paleta arriba.',
  'Original blue': 'Azul original',
  '{description} It needs a model of about {size} MB.': '{description} Necesita un modelo de unos {size} MB.',
  'Model installed': 'Modelo instalado',
  'Model not installed': 'Modelo no instalado',
  'Download failed: {error}': 'La descarga falló: {error}',
  'The server answers.': 'El servidor responde.',
  'Live collaboration': 'Colaboración en vivo',
  'Work on a note together with others at the same time. Everything is sealed with a key that only the invite link holds; the signalling server only introduces your devices to each other and sees nothing of the note (but it does see the addresses of the devices that connect, and when). You can use the one that comes with the app or run your own: the source has versions for Cloudflare Workers, Node and Dart in tool/signaling. Everyone in a session uses the server of whoever made the invite.': 'Trabaja en una nota con otros al mismo tiempo. Todo va sellado con una clave que solo tiene el enlace de invitación; el servidor de señalización solo presenta tus dispositivos entre sí y no ve nada de la nota (pero sí ve las direcciones de los dispositivos que se conectan, y cuándo). Puedes usar el que trae la aplicación o ejecutar el tuyo: el código tiene versiones para Cloudflare Workers, Node y Dart en tool/signaling. Todos en una sesión usan el servidor de quien hizo la invitación.',
  'Built-in server': 'Servidor integrado',
  'My own server': 'Mi propio servidor',
  'Test and use': 'Probar y usar',
  'Using the built-in server.': 'Usando el servidor integrado.',
  'Your name in sessions': 'Tu nombre en las sesiones',
  'Note files': 'Archivos de nota',
  'A note can be saved as one file (.uninote, a ZIP with the text, the strokes, pictures and the PDF) to keep, send, or open on another device: use "Save this note as a file" in the note, or the menu of a note. To have a file made by itself whenever a note was changed (into a folder that a sync program watches, say), add the automation "Save the note as a file" in the Automations tab.': 'Una nota se puede guardar como un solo archivo (.uninote, un ZIP con el texto, los trazos, las imágenes y el PDF) para conservarla, enviarla o abrirla en otro dispositivo: usa «Guardar esta nota como archivo» en la nota o en su menú. Para que se cree un archivo solo cada vez que cambie una nota (por ejemplo, en una carpeta que vigila un programa de sincronización), añade la automatización «Guardar la nota como archivo» en la pestaña Automatizaciones.',
  'Open a note file...': 'Abrir un archivo de nota...',
  'Sorting notes': 'Ordenar notas',
  'Sentence model': 'Modelo de frases',
  'Reads the meaning of a note with a small language model (a sentence transformer, Apache-2.0 licence). It files notes by the automation "Move the note to the folder it fits best", finds the passages that answer a question across all notes, and makes the graph follow the meaning. It runs on this device; nothing is sent away.': 'Lee el significado de una nota con un modelo de lenguaje pequeño (un transformador de frases, licencia Apache-2.0). Ordena las notas con la automatización «Mover la nota a la carpeta que mejor le corresponda», encuentra los pasajes que responden a una pregunta en todas las notas y hace que el grafo siga el significado. Se ejecuta en este dispositivo; no se envía nada fuera.',
  'The automation "Move the note to the folder it fits best" reads the words of a note with a small language model (a sentence transformer, Apache-2.0 licence) and files it with the notes it resembles. It runs on this device; nothing is sent away.': 'La automatización «Mover la nota a la carpeta que mejor le corresponda» lee las palabras de una nota con un modelo de lenguaje pequeño (un transformador de frases, licencia Apache-2.0) y la archiva junto a las notas a las que se parece. Se ejecuta en este dispositivo; no se envía nada fuera.',
  'Handwriting': 'Escritura a mano',
  'Select drawings with the lasso and choose "Convert handwriting to text". Reading happens on this device; nothing is sent away.': 'Selecciona dibujos con el lazo y elige «Convertir escritura a texto». La lectura se hace en este dispositivo; no se envía nada fuera.',
  'Which model reads the handwriting': 'Qué modelo lee la escritura',
  'GLM-OCR (MIT licence) reads each line of your writing as a picture, with the knowledge of a language model about which words are likely: far better than the others on German and English notes. About 800 MB to download and two to three gigabytes of memory while it reads; it may correct a word to English or write maths as LaTeX.': 'GLM-OCR (licencia MIT) lee cada línea de tu escritura como una imagen, con el conocimiento de un modelo de lenguaje sobre qué palabras son probables: mucho mejor que los demás en notas en alemán e inglés. Unos 800 MB de descarga y de dos a tres GB de memoria mientras lee; puede corregir una palabra al inglés o escribir matemáticas en LaTeX.',
  'How carefully it looks': 'Cuidado al leer',
  'Quick': 'Rápido',
  'Quick takes about two thirds of the time and reads a little less exactly. Light takes less than half of it and reads clearly less exactly: for a slow device.': 'Rápido tarda unas dos terceras partes del tiempo y lee un poco menos exactamente. Ligero tarda menos de la mitad y lee bastante menos exactamente: para un dispositivo lento.',
  'PaddleOCR-VL (Apache 2.0 licence) is a much bigger model: about 900 MB to download, a gigabyte or two of memory while it reads, and slow on a tablet. It reads each line of your writing as a picture, with the knowledge of a language model about which words are likely.': 'PaddleOCR-VL (licencia Apache 2.0) es un modelo mucho más grande: unos 900 MB de descarga, de uno a dos GB de memoria mientras lee, y lento en una tableta. Lee cada línea de tu escritura como una imagen, con el conocimiento de un modelo de lenguaje sobre qué palabras son probables.',
  'Formulas': 'Fórmulas',
  'Select a handwritten formula with the lasso and choose "Convert a handwritten formula to LaTeX". Reading happens on this device; nothing is sent away.': 'Selecciona una fórmula escrita a mano con el lazo y elige «Convertir una fórmula escrita a mano a LaTeX». La lectura se hace en este dispositivo; no se envía nada fuera.',
  'Which model reads the formulas': 'Qué modelo lee las fórmulas',
  'TexTeller (Apache 2.0 licence) reads handwriting far better, but is bigger and slower. It suits a computer or a fast tablet.': 'TexTeller (licencia Apache 2.0) lee la escritura a mano bastante mejor, pero es más grande y lento. Va bien en un ordenador o en una tableta rápida.',
  'Pix2Text (MIT licence) is lighter and quicker, but made for printed formulas and poor at handwriting. Use it if the device is slow or short of memory.': 'Pix2Text (licencia MIT) es más ligero y rápido, pero está hecho para fórmulas impresas y es malo con la escritura a mano. Úsalo si el dispositivo es lento o le falta memoria.',
  'AI assistant': 'Asistente de IA',
  'Highlight text and choose "Summarize" (more than two words), "Tell me more" or "Ask a question"; the sparkle button in a note opens an assistant that answers questions about the whole document. Who answers is up to you; the text you highlight goes to that provider only.': 'Resalta texto y elige «Resumir» (más de dos palabras), «Cuéntame más» o «Hacer una pregunta»; el botón de destello de una nota abre un asistente que responde preguntas sobre todo el documento. Quién responde lo decides tú; el texto resaltado solo va a ese proveedor.',
  'Prompt for "Summarize"': 'Instrucción para «Resumir»',
  'Standing instructions': 'Instrucciones permanentes',
  'Request': 'Solicitud',
  '{text} is the highlighted text, {length} how long the summary should be': '{text} es el texto resaltado, {length} la longitud que debe tener el resumen',
  'Length': 'Longitud',
  'Back to the standard prompt': 'Volver a la instrucción estándar',
  'Found on this computer. Needs {needs}.': 'Encontrado en este ordenador. Necesita {needs}.',
  'Needs {needs}.': 'Necesita {needs}.',
  'The download failed: {why}': 'La descarga falló: {why}',
  'No graphics card runtime downloaded yet. Pick one above; it is used from the next start of the app.': 'Todavía no se ha descargado ningún entorno de tarjeta gráfica. Elige uno arriba; se usará desde el próximo inicio de la aplicación.',
  'NVIDIA graphics card (CUDA 13)': 'Tarjeta gráfica NVIDIA (CUDA 13)',
  'NVIDIA graphics card (CUDA 12)': 'Tarjeta gráfica NVIDIA (CUDA 12)',
  'AMD graphics card (ROCm)': 'Tarjeta gráfica AMD (ROCm)',
  'Intel graphics card / NPU (OpenVINO)': 'Tarjeta gráfica Intel / NPU (OpenVINO)',
  'the NVIDIA driver 580 or newer, and CUDA 13 with cuDNN': 'el controlador NVIDIA 580 o posterior, y CUDA 13 con cuDNN',
  'the NVIDIA driver, and CUDA 12 with cuDNN': 'el controlador NVIDIA, y CUDA 12 con cuDNN',
  'ROCm 7.1': 'ROCm 7.1',
  'the Intel compute runtime': 'el entorno de cómputo de Intel',
  'This computer has a graphics card ({names}), but the app is running on the runtime for the processor. Download the runtime for it below, then start the app again.': 'Este ordenador tiene una tarjeta gráfica ({names}), pero la aplicación se ejecuta con el entorno del procesador. Descarga abajo el que le corresponde y luego vuelve a iniciar la aplicación.',
  'Show extra small models': 'Mostrar los modelos extra pequeños',
  'Hide extra small models': 'Ocultar los modelos extra pequeños',
  'not saved yet': 'aún no guardado',
  'Prompt for "Tell me more"': 'Instrucción para «Cuéntame más»',
  '{text} is the highlighted text': '{text} es el texto resaltado',
  'Prompt for "Ask a question"': 'Instrucción para «Hacer una pregunta»',
  '{text} is the highlighted text, {question} what you ask': '{text} es el texto resaltado, {question} lo que preguntas',
  'Prompt for the document assistant': 'Instrucción para el asistente de documentos',
  '{text} is the passages of the document found for the question, {question} what you ask': '{text} son los pasajes del documento encontrados para la pregunta, {question} lo que preguntas',
  'Model': 'Modelo',
  'Use this': 'Usar este',
  'Ready': 'Listo',
  'Needs a download of about {size} GB': 'Necesita una descarga de unos {size} GB',
  'Answer in one short sentence.': 'Responde en una frase corta.',
  'Say that the connection works.': 'Di que la conexión funciona.',
  'Connected (the answer was empty).': 'Conectado (la respuesta estaba vacía).',
  'Connected: {answer}': 'Conectado: {answer}',
  'Address': 'Dirección',
  'e.g. https://api.openai.com/v1 or http://localhost:11434/v1': 'p. ej. https://api.openai.com/v1 o http://localhost:11434/v1',
  'e.g. gpt-4o-mini or llama3.2': 'p. ej. gpt-4o-mini o llama3.2',
  'API key': 'Clave de API',
  'A key is saved in this device\'s keystore; leave empty to keep it. Servers on your own machine often need none.': 'La clave se guarda en el almacén de claves de este dispositivo; déjala vacía para conservarla. Los servidores en tu propio equipo suelen no necesitarla.',
  'Kept in this device\'s keystore. Servers on your own machine often need none.': 'Se guarda en el almacén de claves de este dispositivo. Los servidores en tu propio equipo suelen no necesitarla.',
  'Trying...': 'Probando...',
  'Save and try': 'Guardar y probar',
  'Delete the key': 'Borrar la clave',
  'AI features': 'Funciones de IA',
  'On': 'Activadas',
  'Off: nothing in the app uses AI': 'Desactivadas: nada de la aplicación usa IA',
  'Turn this off and every AI feature goes away at once: the assistant, summaries and questions about highlighted text, smart task titles, reading handwriting and formulas. Nothing is run, and nothing is sent to an AI service. Your downloads and settings below stay as they are.': 'Si lo desactivas, todas las funciones de IA desaparecen a la vez: el asistente, los resúmenes y las preguntas sobre el texto resaltado, los títulos inteligentes de las tareas, la lectura de la escritura a mano y de las fórmulas. No se ejecuta nada y no se envía nada a un servicio de IA. Tus descargas y ajustes de abajo se quedan como están.',
  'Language': 'Idioma',
  'The language of the menus and messages. By default the language of the device is used.': 'El idioma de los menús y mensajes. Por defecto se usa el idioma del dispositivo.',
  'Device language': 'Idioma del dispositivo',
