  'Open a shared note?': '¿Abrir una nota compartida?',
  '{who} shared a copy of a note with you. It is downloaded from {host} and opened as a new note of your own.': '{who} ha compartido contigo una copia de una nota. Se descarga desde {host} y se abre como una nota nueva tuya.',
  'Downloading the note...': 'Descargando la nota...',
  'Could not open the shared note: {error}': 'No se pudo abrir la nota compartida: {error}',
  'Sharing a copy needs a Nextcloud account (connect one in the settings under Sync and sharing).': 'Compartir una copia necesita una cuenta de Nextcloud (conéctala en los ajustes, en Sincronización y uso compartido).',
  'The Nextcloud did not accept the login. Connect again in the settings under Sync and sharing.': 'Nextcloud no aceptó el inicio de sesión. Vuelve a conectar en los ajustes, en Sincronización y uso compartido.',
  'The Nextcloud did not make a public link. Is link sharing turned on for it?': 'Nextcloud no creó un enlace público. ¿Está activado el uso compartido por enlace?',
  'The Nextcloud answered with an error ({code}).': 'Nextcloud respondió con un error ({code}).',
  'Someone shared something with you': 'Alguien compartió algo contigo',
  '{n} things were shared with you': 'Se compartieron {n} cosas contigo',
  'Could not look for shares given to you. {why}': 'No se pudo buscar lo que se compartió contigo. {why}',
  'The Nextcloud refused {method} at {url} (405). Check that the address of the Nextcloud in the settings under Sync and sharing is the one you open in the browser.': 'Nextcloud rechazó {method} en {url} (405). Comprueba que la dirección del Nextcloud en los ajustes, en Sincronización y uso compartido, es la que abres en el navegador.',
  'This link does not use a secure address.': 'Este enlace no usa una dirección segura.',
  'This shared copy is gone: it expired or was taken down.': 'Esta copia compartida ya no existe: caducó o fue retirada.',
  'The shared copy could not be downloaded ({code}).': 'No se pudo descargar la copia compartida ({code}).',
  'This shared copy is too big.': 'Esta copia compartida es demasiado grande.',
  'This calendar is too big.': 'Este calendario es demasiado grande.',
  'This copy cannot be opened: the link is incomplete, or the file was changed.': 'Esta copia no se puede abrir: el enlace está incompleto o el archivo se ha modificado.',
  'Puts a sealed copy of this note on {service} and makes a link to it. Whoever opens the link gets their own copy, even while you are offline. Only the link can open the copy; {service} sees a file it cannot read. The link works for {days} days.': 'Guarda una copia cifrada de esta nota en {service} y crea un enlace a ella. Quien abra el enlace obtiene su propia copia, incluso si tú estás sin conexión. Solo el enlace puede abrir la copia; {service} ve un archivo que no puede leer. El enlace funciona durante {days} días.',
  'Connect {service} first.': 'Conecta primero {service}.',
  'Connect a Nextcloud in the settings under Sync and sharing first.': 'Conecta primero un Nextcloud en los ajustes, en Sincronización y uso compartido.',
  'There is no service to share through.': 'No hay ningún servicio para compartir.',
