  'The sign-in has run out. Sign in again.': 'El inicio de sesión caducó. Inicia sesión de nuevo.',
  'Sign in to {service} in the settings first.': 'Primero inicia sesión en {service} en los ajustes.',
  'OneDrive did not accept the sign-in. Sign in again in the settings.': 'OneDrive no aceptó el inicio de sesión. Vuelve a iniciarlo en los ajustes.',
  'OneDrive does not allow links for anyone here (work and school accounts often forbid them).': 'OneDrive no permite enlaces para cualquiera aquí (las cuentas de trabajo y de centro educativo suelen prohibirlos).',
  'Your OneDrive is full.': 'Tu OneDrive está lleno.',
  'OneDrive answered with an error ({code}).': 'OneDrive respondió con un error ({code}).',
  'S3 storage': 'Almacenamiento S3',
  'Set up S3 storage in the settings first.': 'Configura primero el almacenamiento S3 en los ajustes.',
  'The secret key is not right.': 'La clave secreta no es correcta.',
  'The access key ID is not known to the service.': 'El servicio no conoce el ID de la clave de acceso.',
  'There is no bucket with that name.': 'No hay ningún bucket con ese nombre.',
  'These keys may not write to that bucket.': 'Es posible que estas claves no puedan escribir en ese bucket.',
  'The service answered with an error ({code}).': 'El servicio respondió con un error ({code}).',
  'Fill in every field.': 'Rellena todos los campos.',
  'The file was stored but cannot be downloaded through a signed link ({code}). Is the region right?': 'El archivo se guardó, pero no se puede descargar con un enlace firmado ({code}). ¿Es correcta la región?',
  'Sharing copies of notes': 'Compartir copias de notas',
  'A copy of a note can be put on a storage service you have an account with, and opened by anyone with the link, also while you are offline. The copy is sealed with a key that is only in the link: the service stores a file it cannot read. Several services can be set up; the one chosen when you share is used.': 'Una copia de una nota se puede guardar en un servicio de almacenamiento en el que tengas cuenta, y la puede abrir cualquiera con el enlace, también sin conexión. La copia va cifrada con una clave que solo está en el enlace: el servicio guarda un archivo que no puede leer. Se pueden configurar varios servicios; se usa el que elijas al compartir.',
  'The address must start with https://': 'La dirección debe empezar por https://',
  'It works. Copies can be shared through this bucket.': 'Funciona. Se pueden compartir copias a través de este bucket.',
  'Any S3-compatible service: Cloudflare R2, Backblaze B2, Wasabi, MinIO, Amazon S3. Make an access key that may read and write in one bucket. Links work for 7 days; the copies are deleted from the bucket after that, the next time you share.': 'Cualquier servicio compatible con S3: Cloudflare R2, Backblaze B2, Wasabi, MinIO, Amazon S3. Crea una clave de acceso que pueda leer y escribir en un solo bucket. Los enlaces funcionan 7 días; después las copias se borran del bucket la próxima vez que compartas.',
  'Bucket {bucket} at {host}': 'Bucket {bucket} en {host}',
  'Service address': 'Dirección del servicio',
