  'Test and save': 'Probar y guardar',
  'The browser could not be opened.': 'No se pudo abrir el navegador.',
  'Copies are put in a folder of the app on your {service}, and the link works for {days} days; the copies are deleted from it after that, the next time you share.': 'Las copias se guardan en una carpeta de la aplicación en tu {service}, y el enlace funciona {days} días; después las copias se borran de ella, la próxima vez que compartas.',
  'Sign in to {service}': 'Iniciar sesión en {service}',
  'Sign out': 'Cerrar sesión',
  'Change': 'Cambiar',
  'While you work on this note in a live session, whoever opens this link is offered to join it.': 'Mientras trabajas en esta nota en una sesión en vivo, a quien abra este enlace se le ofrece unirse.',
  'Someone is working on this note right now': 'Alguien está trabajando en esta nota ahora mismo',
  '{who} is in a live session on this note. Join it and work on the note together, or open a copy of your own?': '{who} está en una sesión en vivo sobre esta nota. ¿Unirte y trabajar juntos en la nota, o abrir una copia propia?',
  'Open a copy': 'Abrir una copia',
  'Join the live session': 'Unirse a la sesión en vivo',
  'App key': 'Clave de la aplicación',
  'Application (client) ID': 'ID de aplicación (cliente)',
  'Dropbox needs an app of your own: create one at dropbox.com/developers/apps ("Scoped access", "App folder"), allow files.content.write and sharing.write, add the redirect URI notation://oauth/dropbox, and enter its app key here.': 'Dropbox necesita una aplicación propia: créala en dropbox.com/developers/apps («Scoped access», «App folder»), permite files.content.write y sharing.write, añade la URI de redirección notation://oauth/dropbox e introduce aquí su clave de aplicación.',
  'OneDrive needs an app of your own: register one in the Azure portal (App registrations, accounts of any kind), add the redirect URI notation://oauth/onedrive for "Mobile and desktop", allow Files.ReadWrite.AppFolder and offline_access, and enter its application ID here.': 'OneDrive necesita una aplicación propia: regístrala en el portal de Azure (App registrations, cuentas de cualquier tipo), añade la URI de redirección notation://oauth/onedrive para «Mobile and desktop», permite Files.ReadWrite.AppFolder y offline_access, e introduce aquí su ID de aplicación.',
