  'Saved "{name}" as a brush of its own.': '«{name}» guardado como pincel propio.',
  'Copied the brush "{name}" as text. Paste it in the designer on another device.': 'El pincel «{name}» se copió como texto. Pégalo en el diseñador en otro dispositivo.',
