  'This is not a brush.': 'Esto no es un pincel.',
  'Some lines of this note are drawn with a brush of the extension {names}, which is not installed or is switched off. They are drawn with the pen.': 'Algunas líneas de esta nota se dibujan con un pincel de la extensión {names}, que no está instalada o está desactivada. Se dibujan con el lápiz.',
