  'Drawing tools of extensions': 'Herramientas de dibujo de extensiones',
  'Drawing tool: {tool}': 'Herramienta de dibujo: {tool}',
  'Plain pen': 'Lápiz simple',
  'Draw on the pages with the drawing tools it lists': 'Dibujar en las páginas con las herramientas de dibujo que indica',
  'A paint roller for the drawing bar: a wide band with streaks.': 'Un rodillo de pintura para la barra de dibujo: una banda ancha con rayas.',
  'Import a PDF to write on, and export a note as a PDF.': 'Importar un PDF para escribir encima, y exportar una nota como PDF.',
  'Languages': 'Idiomas',
  'Lasso': 'Lazo',
  'Law, business, economics and social sciences': 'Derecho, economía, empresa y ciencias sociales',
  'Lines drawn nearly straight are straightened, and drawings very close to a rectangle, ellipse, triangle or diamond become that shape.': 'Las líneas trazadas casi rectas se enderezan, y los dibujos muy cercanos a un rectángulo, una elipse, un triángulo o un rombo se convierten en esa forma.',
  'Lines, arrows, rectangles and ellipses drawn with the pen.': 'Líneas, flechas, rectángulos y elipses dibujados con el lápiz.',
  'Live sessions and shared copies of notes with other people.': 'Sesiones en vivo y copias compartidas de notas con otras personas.',
  'Look things up': 'Buscar información',
  'Made for you now and kept. If two people with the same name work together, it tells them apart. It is not a password.': 'Creado para ti ahora y guardado. Si dos personas con el mismo nombre trabajan juntas, lo distingue. No es una contraseña.',
  'Made for you the first time the app started and kept. It tells two people with the same name apart when you work on a note together. It is not a password.': 'Creado para ti la primera vez que se inició la aplicación, y guardado. Distingue a dos personas con el mismo nombre cuando trabajáis juntos en una nota. No es una contraseña.',
  'Mathematics and physics': 'Matemáticas y física',
  'Maths': 'Mates',
  'Next': 'Siguiente',
  'Notes you write and draw, PDFs you annotate, and notes you work on together with others.': 'Notas que escribes y dibujas, PDF que anotas, y notas que trabajas junto con otros.',
  'Only the basics': 'Solo lo básico',
  'Organising and sharing': 'Organización y compartir',
  'Other people see this name when you work on a note together, and it goes on what you add to a note, so the history can show who wrote what.': 'Otras personas ven este nombre cuando trabajan juntas en una nota, y aparece en lo que añades a una nota, para que el historial muestre quién escribió qué.',
  'PDF': 'PDF',
  'Philosophy, history and literature': 'Filosofía, historia y literatura',
  'Pictures': 'Imágenes',
  'Plots': 'Gráficas',
  'Put pictures on a page.': 'Poner imágenes en una página.',
  'Reading and looking things up': 'Leer y buscar información',
  'Reading texts closely, quoting and arguing in writing.': 'Leer textos con detalle, citar y argumentar por escrito.',
  'Rules that sort, title and file notes by themselves.': 'Reglas que ordenan, titulan y archivan las notas por sí solas.',
  'Save a note as a file (.uninote) and open one.': 'Guardar una nota como archivo (.uninote) y abrir uno.',
  'Search the web, Wikipedia and translate from selected text, with the page beside the note.': 'Buscar en la web, Wikipedia y traducir desde el texto seleccionado, con la página junto a la nota.',
  'Select, move, copy and delete drawings, text boxes and pictures by drawing around them.': 'Seleccionar, mover, copiar y borrar dibujos, cuadros de texto e imágenes dibujando alrededor de ellos.',
  'Set up for what you use the app for:': 'Preparado para lo que usas la aplicación:',
  'Shapes': 'Formas',
  'Sharing notes and writing them together.': 'Compartir notas y escribirlas en conjunto.',
  'Show everything': 'Mostrar todo',
  'Show me everything': 'Muéstrame todo',
  'Show the intro again': 'Volver a mostrar la introducción',
  'Sketches, pictures and layouts.': 'Bocetos, imágenes y maquetas.',
  'Skip': 'Omitir',
  'Every tool is on.': 'Todas las herramientas están activadas.',
  'Nothing chosen: you start with the basics. More tools can be switched on in the settings at any time.': 'No has elegido nada: empiezas con lo básico. Puedes activar más herramientas en los ajustes cuando quieras.',
  'Everyday notes and meetings': 'Notas del día a día y reuniones',
  'Lists, meeting notes, to-dos and things to remember.': 'Listas, notas de reuniones, tareas y cosas que recordar.',
  'Everyday': 'Día a día',
  'Straight lines and shapes': 'Líneas rectas y formas',
  'Switch off what you do not use and it goes away from the screens. Nothing is deleted: notes that use a tool that is off stay as they are.': 'Desactiva lo que no uses y desaparece de las pantallas. No se borra nada: las notas que usan una herramienta desactivada se quedan como están.',
  'Tables': 'Tablas',
  'Tables in text boxes and in the written document.': 'Tablas en cuadros de texto y en el documento escrito.',
  'The calendar, the week view, tasks and syncing them.': 'El calendario, la vista semanal, las tareas y su sincronización.',
  'The name other people see in live sessions, on what you add to a note, and in the history of a note.': 'El nombre que otros ven en las sesiones en vivo, en lo que añades a una nota y en el historial de una nota.',
  'Their id: {id}': 'Su ID: {id}',
  'Theme images': 'Imágenes de tema',
  'A few quick steps make it fit you: what to call you, what you use it for, and which tools you want to see. You can change all of it later in the settings.': 'Unos pasos rápidos para adaptarla a ti: cómo llamarte, para qué la usas y qué herramientas quieres ver. Puedes cambiarlo todo después en los ajustes.',
  'Tools': 'Herramientas',
  'Turn a handwritten formula into LaTeX (needs the model from the settings).': 'Convierte una fórmula escrita a mano en LaTeX (necesita el modelo de los ajustes).',
  'Turn handwriting into text (needs the model from the settings).': 'Convierte escritura a mano en texto (necesita el modelo de los ajustes).',
  'Unnamed': 'Sin nombre',
  'Vocabulary, grammar and texts in more than one language.': 'Vocabulario, gramática y textos en más de un idioma.',
  'Welcome to Notation': 'Bienvenido a Notation',
  'What should we call you?': '¿Cómo te llamamos?',
  'What will you use Notation for?': '¿Para qué usarás Notation?',
  'Working together': 'Trabajo en conjunto',
  'Working with others': 'Trabajar con otros',
  'Writing and drawing': 'Escribir y dibujar',
  'Creative tools': 'Herramientas creativas',
  'More brushes': 'Más pinceles',
  'Pencil, fountain pen, calligraphy nib, marker, charcoal, airbrush and watercolour for the drawing bar.': 'Lápiz, pluma, plumilla de caligrafía, rotulador, carboncillo, aerógrafo y acuarela para la barra de dibujo.',
  'Symmetry drawing': 'Dibujo con simetría',
  'Draw with a mirror or around a centre: what you draw is repeated on the other side or in turns (mandalas, patterns).': 'Dibuja con un espejo o alrededor de un centro: lo que dibujas se repite al otro lado o en giros (mandalas, patrones).',
  'Line stabiliser': 'Estabilizador de trazo',
  'Smooths a shaky hand: the line follows the pen with a little delay, for clean lettering and line art.': 'Suaviza una mano temblorosa: la línea sigue a la pluma con un ligero retraso, para letras limpias y dibujo lineal.',
  'Pencil': 'Lápiz',
  'Fountain pen': 'Pluma',
  'Calligraphy': 'Caligrafía',
  'Marker': 'Rotulador',
  'Charcoal': 'Carboncillo',
  'Airbrush': 'Aerógrafo',
  'Watercolour': 'Acuarela',
  'Line stabiliser: {level}': 'Estabilizador de trazo: {level}',
