  'Light': 'Ligero',
  'Medium': 'Medio',
  'Strong': 'Fuerte',
  'Symmetry: {kind}': 'Simetría: {kind}',
  'Mirror left and right': 'Espejo izquierda y derecha',
  'Mirror up and down': 'Espejo arriba y abajo',
  'Mirror both ways': 'Espejo en ambas direcciones',
  'Around the centre': 'Alrededor del centro',
  'Around the centre, mirrored': 'Alrededor del centro, en espejo',
  '{n} turns': '{n} giros',
  'You': 'Tú',
  'You can leave the name empty and set it later.': 'Puedes dejar el nombre vacío y ponerlo más tarde.',
  'Your id: {id}': 'Tu ID: {id}',
  'Your name': 'Tu nombre',
  'Your tools': 'Tus herramientas',
  'Smart features': 'Funciones inteligentes',
  'Everything on these pages was made by the app. Write on it, change it, delete it: it is only here to try things on.': 'Todo lo que hay en estas páginas lo creó la aplicación. Escribe encima, cámbialo o bórralo: solo está para probar cosas.',
  'Everything in this note was made by the app. Write on it, change it, delete it: it is only here to try things on.': 'Todo lo que hay en esta nota lo creó la aplicación. Escribe encima, cámbialo o bórralo: solo está para probar cosas.',
  'Write like a document': 'Escribir como un documento',
  'This page is a written document: **bold**, *italic*, `code` and ==highlights== are just Markdown, and the bar at the side formats the text for you. Headings, the table of contents above, tables, pictures and footnotes[^1] all work, and it prints as pages.': 'Esta página es un documento escrito: **negrita**, *cursiva*, `código` y ==resaltados== son Markdown, y la barra lateral da formato al texto por ti. Los títulos, el índice de arriba, las tablas, las imágenes y las notas al pie[^1] funcionan, y se imprime en páginas.',
  'Pick the pen in the drawing bar and write anywhere, with a stylus or a finger. Draw a ring round something with the lasso to move, copy or delete it. A note can hold both: the written document first, then pages to draw on.': 'Elige el lápiz en la barra de dibujo y escribe en cualquier lugar, con un lápiz óptico o con el dedo. Dibuja un círculo alrededor de algo con el lazo para moverlo, copiarlo o borrarlo. Una nota puede tener ambas cosas: primero el documento escrito y luego páginas para dibujar.',
  'A mind map, a state machine, a search tree and a graph with its shortest ways: drawn from text, on the next page. The facts under each were worked out by the app.': 'Un mapa mental, una máquina de estados, un árbol de búsqueda y un grafo con sus caminos más cortos: dibujados a partir de texto, en la página siguiente. Los datos bajo cada uno los calculó la aplicación.',
  'Like this one. The next page is a notebook page: draw on it.': 'Como esta. La página siguiente es una hoja de cuaderno: dibuja en ella.',
  'Write and draw': 'Escribir y dibujar',
  'Pen and highlighter': 'Lápiz y resaltador',
  'Lasso and layers': 'Lazo y capas',
  'Check my working': 'Comprobar mi procedimiento',
  'Solve and plot': 'Resolver y representar',
  'Diagrams': 'Diagramas',
  'Mind maps': 'Mapas mentales',
  'Automata, trees, graphs': 'Autómatas, árboles, grafos',
  'Together': 'Juntos',
  'Live sessions': 'Sesiones en vivo',
  'A mind map, made from a list with the diagram button.': 'Un mapa mental, hecho a partir de una lista con el botón de diagrama.',
  'Pick the pen in the drawing bar and write anywhere, with a stylus or a finger. Draw a ring round something with the lasso to move, copy or delete it. Double-tap the page (triple-click on a computer) to add a text box like this one.': 'Elige el lápiz en la barra de dibujo y escribe en cualquier lugar, con un lápiz óptico o con el dedo. Dibuja un círculo alrededor de algo con el lazo para moverlo, copiarlo o borrarlo. Haz doble toque en la página (triple clic en un ordenador) para añadir un cuadro de texto como este.',
  'Write a worked solution by hand. A moment later each line gets a green check or a red cross; tap it to see what was checked. Like this:': 'Escribe a mano una solución resuelta. Un momento después cada línea recibe una marca verde o una cruz roja; tócala para ver qué se comprobó. Como esto:',
  'End a calculation with = and the result appears:': 'Termina un cálculo con = y aparecerá el resultado:',
  'true in every row': 'verdadero en cada fila',
  'false in every row': 'falso en cada fila',
  'true in {n} of {rows} rows': 'verdadero en {n} de {rows} filas',
  'Truth tables': 'Tablas de verdad',
  'The grid button makes the truth table of a formula, with a column for every part of it. This is (p ∧ q) → r:': 'El botón de cuadrícula crea la tabla de verdad de una fórmula, con una columna para cada parte. Esta es (p ∧ q) → r:',
  'Diagrams from a few lines of text': 'Diagramas a partir de unas pocas líneas de texto',
  'A state machine, a search tree and a graph with its shortest ways, drawn from text. The facts under each were worked out by the app.': 'Una máquina de estados, un árbol de búsqueda y un grafo con sus caminos más cortos, dibujados a partir de texto. Los datos bajo cada uno los calculó la aplicación.',
  'Flashcards from your notes and your mistakes': 'Tarjetas de estudio con tus notas y tus errores',
  'Citations with [@key] and a list of sources': 'Citas con [@clave] y una lista de fuentes',
  'PDFs to write on, and notes as PDF': 'PDF para escribir encima, y notas como PDF',
  'A calendar and tasks': 'Un calendario y tareas',
  'Notes written together, live': 'Notas escritas juntos, en vivo',
  'And more': 'Y más',
  'The settings hold the tools you can switch on and off, the models to download and the switch for all the AI features.': 'Los ajustes contienen las herramientas que puedes activar o desactivar, los modelos para descargar y el interruptor de todas las funciones de IA.',
  'Language, colour and pen': 'Idioma, color y lápiz',
  'All of this can be changed later in the settings.': 'Todo esto se puede cambiar después en los ajustes.',
  'Try your pen': 'Prueba tu lápiz',
  'Write or draw in the box with the pen, a finger or the mouse.': 'Escribe o dibuja en el recuadro con el lápiz, un dedo o el ratón.',
  'What a finger does': 'Lo que hace un dedo',
  'A pen was found, and it tells how hard it presses.': 'Se detectó un lápiz, y dice cuánta presión ejerce.',
  'A pen was found.': 'Se detectó un lápiz.',
  'A finger was found. If you have a pen, try it too.': 'Se detectó un dedo. Si tienes un lápiz, pruébalo también.',
  'A mouse was found.': 'Se detectó un ratón.',
  'Where your notes live': 'Dónde viven tus notas',
  'Your notes are kept on this device, in the app. Nothing is sent anywhere unless you set it up.': 'Tus notas se guardan en este dispositivo, dentro de la aplicación. No se envía nada a ningún sitio salvo que lo configures.',
  'Use it on more than one device?': '¿La usas en más de un dispositivo?',
  'Link this device with your others to keep the notes, folders and settings the same on all of them.': 'Vincula este dispositivo con tus otros dispositivos para que las notas, carpetas y ajustes sean iguales en todos.',
  'Set up syncing': 'Configurar la sincronización',
  'Syncing': 'Sincronización',
  'Not now is fine: it is in the settings whenever you want it.': '«Ahora no» está bien: está en los ajustes cuando quieras.',
  'The download of "{name}" did not work. You can try again in the settings.': 'La descarga de «{name}» no funcionó. Puedes volver a intentarlo en los ajustes.',
  'You can carry on: the download continues in the background.': 'Puedes seguir: la descarga continúa en segundo plano.',
  '**Welcome to Notation**\nThis page shows what you can do. You can write on it, change it or delete it: it is only here to try things on.': '**Bienvenido a Notation**\nEsta página muestra lo que puedes hacer. Puedes escribir en ella, cambiarla o borrarla: solo está para probar cosas.',
  '**Write and draw**\nPick the pen in the drawing bar and write anywhere on the page, with a stylus or a finger. Draw a ring round something with the lasso to move, copy or delete it. Double-tap the page (triple-click on a computer) to add a text box like this one.': '**Escribir y dibujar**\nElige el lápiz en la barra de dibujo y escribe en cualquier lugar de la página, con un lápiz óptico o con el dedo. Dibuja un círculo alrededor de algo con el lazo para moverlo, copiarlo o borrarlo. Haz doble toque en la página (triple clic en un ordenador) para añadir un cuadro de texto como este.',
  '**Tables and truth tables**\nThe table button in the insert bar makes a table. The grid button next to it makes the truth table of a formula, like this one for p → q:': '**Tablas y tablas de verdad**\nEl botón de tabla de la barra de insertar crea una tabla. El botón de cuadrícula al lado crea la tabla de verdad de una fórmula, como esta para p → q:',
  '**Mind maps and diagrams**\nThe diagram button turns an outline, or lines such as Start -> Check -> Done, into a mind map or a flowchart. In advanced mode it draws a state machine, a tree or a graph from a text and tells you what is true about it.': '**Mapas mentales y diagramas**\nEl botón de diagrama convierte un esquema, o líneas como Inicio -> Revisar -> Hecho, en un mapa mental o un diagrama de flujo. En modo avanzado dibuja una máquina de estados, un árbol o un grafo a partir de un texto y te dice qué es verdad sobre él.',
  '**Maths**\nWrite a calculation by hand and end it with = to see the result. With "Check my maths" on, each line of a worked solution gets a green check or a red cross a moment after you write it; tap the mark to see what was checked and to correct what was read. This needs the formula model from the settings.': '**Matemáticas**\nEscribe un cálculo a mano y termínalo con = para ver el resultado. Con «Comprobar mis mates» activado, cada línea de una solución recibe una marca verde o una cruz roja poco después de escribirla; toca la marca para ver qué se comprobó y corregir lo que se leyó. Esto necesita el modelo de fórmulas de los ajustes.',
  '**Handwriting to text**\nSelect some handwriting to turn it into text. This needs the handwriting model from the settings.': '**Escritura a mano a texto**\nSelecciona escritura a mano para convertirla en texto. Esto necesita el modelo de escritura a mano de los ajustes.',
  '**Where to go from here**\nThe settings hold the tools you can switch on and off, the models to download and the switch for all the AI features. Every tool in the bar has a tip when you hold the pointer over it or press and hold.': '**Y ahora qué**\nLos ajustes contienen las herramientas que puedes activar o desactivar, los modelos para descargar y el interruptor de todas las funciones de IA. Cada herramienta de la barra tiene un consejo al poner el puntero encima o al mantener pulsado.',
  'Make a note that shows the tools': 'Crear una nota que muestre las herramientas',
  'One page, with the tools you chose on it, to try them on. You can delete it.': 'Una página, con las herramientas que elegiste, para probarlas. Puedes borrarla.',
  'Reading your handwriting, checking your maths and the assistant run on this device. Each needs a model that is downloaded once.': 'La lectura de tu escritura, la comprobación de las mates y el asistente se ejecutan en este dispositivo. Cada una necesita un modelo que se descarga una vez.',
  'Turn this off and no AI feature is offered and nothing is downloaded. You can turn it on later in the settings.': 'Si lo desactivas, no se ofrece ninguna función de IA y no se descarga nada. Puedes activarlo más tarde en los ajustes.',
  'Already on this device': 'Ya en este dispositivo',
  '{description} About {size} MB.': '{description} Unos {size} MB.',
  'Nothing will be downloaded.': 'No se descargará nada.',
  'The download of {size} MB starts when you leave this step and runs in the background; the settings show how far it is.': 'La descarga de {size} MB empieza al salir de este paso y sigue en segundo plano; los ajustes muestran cuánto falta.',
  'Turns what you write by hand into text, to search and copy.': 'Convierte lo que escribes a mano en texto, para buscar y copiar.',
  'Formulas and maths check': 'Fórmulas y comprobación de mates',
  'Reads handwritten formulas and marks your working line by line.': 'Lee fórmulas escritas a mano y marca tu procedimiento línea a línea.',
  'Answers questions about a note and summarises it. A big download, so it is only on if you tick it.': 'Responde preguntas sobre una nota y la resume. Es una descarga grande, así que solo se activa si la marcas.',
  'Duplicate drawing': 'Duplicar dibujo',
  'Duplicate the selection': 'Duplicar la selección',
  'Duplicate text box': 'Duplicar cuadro de texto',
  'Duplicate picture': 'Duplicar imagen',
  'Read the writing and formulas ahead of time, so converting them is instant': 'Leer la escritura y las fórmulas por adelantado, para convertirlas al instante',
  'Reads the handwriting ahead of time': 'Lee la escritura a mano por adelantado',
  'Reads the formulas ahead of time': 'Lee las fórmulas por adelantado',
  'Reads the handwriting and the formulas ahead of time': 'Lee la escritura a mano y las fórmulas por adelantado',
  'The handwriting and formula readers are switched off (see Settings)': 'Los lectores de escritura y fórmulas están desactivados (ver ajustes)',
  'The models are not installed (see Settings)': 'Los modelos no están instalados (ver ajustes)',
  'Check my maths': 'Comprobar mis mates',
  'Marks the maths you write as right or wrong, line by line, a moment after you wrote it, and gives the result of a line that ends with =. Needs the formula model from the settings.': 'Marca las matemáticas que escribes como correctas o incorrectas, línea a línea, poco después de escribirlas, y da el resultado de una línea que termina en =. Necesita el modelo de fórmulas de los ajustes.',
  'This looks right': 'Esto parece correcto',
  'Right, up to rounding': 'Correcto, salvo redondeo',
  'The sum does not work out': 'La suma no sale',
  'The two sides are not equal': 'Los dos lados no son iguales',
  'That is not the derivative': 'Esa no es la derivada',
  'That is not the integral': 'Esa no es la integral',
  'That is not the limit': 'Ese no es el límite',
  'That does not solve the line above': 'Eso no resuelve la línea de arriba',
  'This does not follow from the line above': 'Eso no se sigue de la línea de arriba',
  'A solution of the line above is lost': 'Se pierde una solución de la línea de arriba',
  'This lets in a solution the line above did not have': 'Esto deja entrar una solución que la línea de arriba no tenía',
  'I read:': 'Leí:',
  'For example:': 'Por ejemplo:',
  'It works out to:': 'Da:',
  'The solution that is missing:': 'La solución que falta:',
  'The solution that is new:': 'La solución nueva:',
  'The line above has:': 'La línea de arriba tiene:',
  'It should be:': 'Debería ser:',
  'Checked by working it out in numbers on this device. If the writing was read wrongly, the check is wrong too.': 'Comprobado calculándolo con números en este dispositivo. Si la escritura se leyó mal, la comprobación también está mal.',
  'The formula model is not installed (see Settings)': 'El modelo de fórmulas no está instalado (ver ajustes)',
  'Checking...': 'Comprobando...',
  'A line could not be read': 'No se pudo leer una línea',
  'Nothing to check in this line': 'Nada que comprobar en esta línea',
  'Check the maths in the selection': 'Comprobar las mates de la selección',
  'Spell checking': 'Corrector ortográfico',
  'Underlines misspelled words in text boxes, the written document and (once read) handwriting, with suggestions. Needs a dictionary from the settings.': 'Subraya las palabras mal escritas en cuadros de texto, en el documento escrito y en la escritura a mano (una vez leída), con sugerencias. Necesita un diccionario de los ajustes.',
  'Misspelled words get a wavy red line in text boxes and the written document; tap one for suggestions. A word is right if the dictionary of any language that is on takes it, so a note in two languages works. The dictionaries are the Hunspell dictionaries of the LibreOffice project, downloaded when you turn a language on (they are not part of the app and have licences of their own). Everything is checked on this device.': 'Las palabras mal escritas llevan una línea roja ondulada en los cuadros de texto y en el documento escrito; toca una para ver sugerencias. Una palabra es correcta si la acepta el diccionario de cualquier idioma activado, así que una nota en dos idiomas funciona. Los diccionarios son los Hunspell del proyecto LibreOffice, que se descargan al activar un idioma (no forman parte de la aplicación y tienen sus propias licencias). Todo se comprueba en este dispositivo.',
  'Your own words': 'Tus propias palabras',
  'Add a word': 'Añadir una palabra',
  'Download about {size} MB': 'Descargar unos {size} MB',
  'Licence: {licence}': 'Licencia: {licence}',
  'see the README': 'ver el README',
  'Delete the dictionary': 'Borrar el diccionario',
  'Licence and README': 'Licencia y README',
  'Add to dictionary': 'Añadir al diccionario',
  'Ignore': 'Ignorar',
  'Not in the dictionary: {word}': 'No está en el diccionario: {word}',
  'Copied: {word}': 'Copiado: {word}',
  'Read as: {word}': 'Leído como: {word}',
  'Read handwriting': 'Leer la escritura a mano',
  'Off: nothing you write is read, so there is no conversion to text, no spell checking of handwriting and no search in it, and the reader does no work in the background.': 'Desactivado: nada de lo que escribes se lee, así que no hay conversión a texto, ni corrección ortográfica de la escritura a mano, ni búsqueda en ella, y el lector no trabaja en segundo plano.',
  'Marking uncertain words': 'Marcado de palabras inciertas',
  'How readily a word the reader was not sure of gets a yellow line (it may have been misread). Rarely marks only the words it was least sure of; often marks more, and more of those are right. Applies to what is read from now on.': 'Con qué facilidad una palabra de la que el lector no estaba seguro recibe una línea amarilla (puede haberse leído mal). Pocas veces marca solo las palabras más inciertas; a menudo marca más, y más de ellas son correctas. Se aplica a lo que se lee a partir de ahora.',
  'Mark words that are spelled right': 'Marcar las palabras bien escritas',
  'In handwriting, a green dotted line under each word that was read and found right (tap it to see what it was read as), to check that your writing was taken for writing.': 'En la escritura a mano, una línea verde de puntos bajo cada palabra leída y considerada correcta (tócala para ver cómo se leyó), para comprobar que tu escritura se tomó como escritura.',
  'This does not hold for:': 'Esto no vale para:',
  'This is not true': 'Esto no es cierto',
  'These matrices are not equal': 'Estas matrices no son iguales',
  'The sizes of these matrices do not fit': 'Los tamaños de estas matrices no encajan',
  'This matrix has no inverse': 'Esta matriz no tiene inversa',
  'These are not congruent': 'Estos no son congruentes',
  'These are not equivalent': 'Estos no son equivalentes',
  'The sizes are:': 'Los tamaños son:',
  'The units do not fit': 'Las unidades no encajan',
  'Did you write one of these?': '¿Escribiste alguna de estas?',
  'The line above:': 'La línea de arriba:',
  'Fix reading': 'Corregir la lectura',
  'Whole solution': 'Solución completa',
  'I am not sure I read this right': 'No estoy seguro de haber leído bien esto',
  'As I read it, this is a mistake, but the writing can be read another way (below). Pick what you wrote:': 'Tal como lo leo, es un error, pero la escritura se puede leer de otra forma (abajo). Elige lo que escribiste:',
  'Or did you write:': '¿O escribiste:',
  'Looked again: it reads the same': 'Revisado: se lee igual',
  'Looking again...': 'Volviendo a mirar...',
  'The units are:': 'Las unidades son:',
  'Its determinant:': 'Su determinante:',
  'They differ at:': 'Difieren en:',
  'I read (correct it if it is wrong):': 'Leí (corrígelo si está mal):',
  'Checked by working it out in numbers on this device. If the writing was read wrongly, correct it above: the check is done again.': 'Comprobado calculándolo con números en este dispositivo. Si la escritura se leyó mal, corrígela arriba: la comprobación se hace de nuevo.',
  'Suggestions are put in order with a list of the most common words of the language (FrequencyWords by Hermit Dave, from film and television subtitles, licence CC BY-SA 4.0), downloaded with the dictionary.': 'Las sugerencias se ordenan con una lista de las palabras más comunes del idioma (FrequencyWords de Hermit Dave, de subtítulos de películas y series, licencia CC BY-SA 4.0), que se descarga con el diccionario.',
  'General': 'General',
  'Tools and writing': 'Herramientas y escritura',
  'AI and models': 'IA y modelos',
  'Sync and sharing': 'Sincronización y uso compartido',
  'A Nextcloud calendar is connected in the settings under Sync and sharing, with the other services.': 'Un calendario de Nextcloud se conecta en los ajustes, en Sincronización y uso compartido, junto con los demás servicios.',
  'Extensions': 'Extensiones',
  'Extensions are small scripts (JavaScript) that add tools to the menu of selected text and actions to the automations. Each runs in a sandbox: it cannot reach your files, the network or your notes unless you give it that permission, it is stopped if it runs too long or uses too much memory, and it is off until you switch it on. Only install extensions from people you trust.': 'Las extensiones son pequeños scripts (JavaScript) que añaden herramientas al menú del texto seleccionado y acciones a las automatizaciones. Cada una se ejecuta en un entorno aislado: no puede acceder a tus archivos, a la red ni a tus notas salvo que le des ese permiso, se detiene si tarda demasiado o usa demasiada memoria, y está desactivada hasta que la actives. Instala solo extensiones de personas en las que confíes.',
  'Install from a file (.zip)': 'Instalar desde un archivo (.zip)',
  'Write one': 'Escribir una',
  'Write an extension': 'Escribir una extensión',
  'The manifest says what it is called, what it adds and what it asks to be allowed to do (JSON):': 'El manifiesto indica cómo se llama, qué añade y qué permisos pide (JSON):',
  'The script (JavaScript):': 'El script (JavaScript):',
  'Install': 'Instalar',
  'No extensions yet.': 'Todavía no hay extensiones.',
  'The script engine is not available on this device: extensions cannot run.': 'El motor de scripts no está disponible en este dispositivo: las extensiones no pueden ejecutarse.',
  'Extensions do not run in the browser: a script there could reach your notes, as the browser cannot keep it apart from them. Use the app on a computer or phone for them.': 'Las extensiones no se ejecutan en el navegador: un script allí podría llegar a tus notas, porque el navegador no puede separarlo de ellas. Usa la aplicación en un ordenador o teléfono para ellas.',
  'Could not install it: {error}': 'No se pudo instalar: {error}',
  'Installed {name}. It is off until you switch it on.': '{name} instalada. Está desactivada hasta que la actives.',
  'It asks to be allowed to:': 'Pide permiso para:',
  'Nothing: it only works on the text it is given.': 'Nada: solo trabaja con el texto que recibe.',
  'Actions': 'Acciones',
  '{name}: {error}': '{name}: {error}',
  'The text changed meanwhile: the result was not put in': 'El texto cambió entretanto: el resultado no se insertó',
