  'Change the text and the title of the note it is used on': 'Cambiar el texto y el título de la nota donde se usa',
  'Add tasks to your calendar': 'Añadir tareas al calendario',
  'Put text on the clipboard': 'Poner texto en el portapapeles',
  'Send requests to the websites it lists': 'Enviar solicitudes a los sitios web que indica',
