  'Extensions are not available here': 'Las extensiones no están disponibles aquí',
  'The extension action is not installed any more': 'La acción de la extensión ya no está instalada',
  'The extension is switched off (see Settings)': 'La extensión está desactivada (ver ajustes)',
  'An extension action that is not installed': 'Una acción de extensión que no está instalada',
  'No extension has an action to run. Install one in Settings > Extensions and switch it on.': 'Ninguna extensión tiene una acción que ejecutar. Instala una en Ajustes > Extensiones y actívala.',
  'Runs an action of an extension, with the permissions you gave it. What it returns is shown as the result of the automation.': 'Ejecuta una acción de una extensión, con los permisos que le diste. Lo que devuelve se muestra como resultado de la automatización.',
  'Choose an action': 'Elegir una acción',
  'Reading the writing ahead of time while the note is open': 'Leer la escritura por adelantado mientras la nota está abierta',
  'While the note is open, the pen strokes that lie close together are grouped and, after things have been quiet for a moment (never while you draw), read in the background. When you then select that writing and convert it, the result is there at once. Needs the models from Settings. Nothing is changed in the note.': 'Mientras la nota está abierta, los trazos de lápiz que están juntos se agrupan y, cuando todo lleva un momento en calma (nunca mientras dibujas), se leen en segundo plano. Cuando después seleccionas esa escritura y la conviertes, el resultado ya está. Necesita los modelos de los ajustes. No se cambia nada en la nota.',
  'Handwriting and formulas': 'Escritura a mano y fórmulas',
