  'Make handwriting selectable in exported PDFs': 'Hacer la escritura a mano seleccionable en los PDF exportados',
  'Puts what the writing says under it, out of sight, so that a PDF viewer can select, copy and search it. What was not read yet is read while the PDF is made (up to a minute).': 'Pone debajo, fuera de la vista, lo que dice la escritura, para que un visor de PDF pueda seleccionarla, copiarla y buscarla. Lo que aún no se ha leído se lee mientras se crea el PDF (hasta un minuto).',
  '1 block of handwriting could not be read in time: it cannot be selected in the PDF': '1 bloque de escritura a mano no pudo leerse a tiempo: no se puede seleccionar en el PDF',
  '{n} blocks of handwriting could not be read in time: they cannot be selected in the PDF': '{n} bloques de escritura a mano no pudieron leerse a tiempo: no se pueden seleccionar en el PDF',
  'Make handwriting searchable': 'Hacer la escritura a mano buscable',
  'Reads the writing of a note while it is open, so that the search finds it. Notes that were not opened since can be read all at once by an automation (when the app starts).': 'Lee la escritura de una nota mientras está abierta, para que la búsqueda la encuentre. Las notas que no se han abierto desde entonces pueden leerse todas a la vez con una automatización (al iniciar la aplicación).',
