  'Pen and fingers': 'Lápiz y dedos',
  'For a stylus on a tablet or a screen that has one. A pen that cannot tell how hard it presses draws lines of one thickness.': 'Para un lápiz óptico en una tableta o en una pantalla que lo admita. Un lápiz que no mide cuánta presión ejerce dibuja líneas de un solo grosor.',
  'Thicker lines where the pen presses harder': 'Líneas más gruesas donde el lápiz presiona más',
  'Sensitivity': 'Sensibilidad',
  'Fewer tools': 'Menos herramientas',
  'More tools: guides, stabiliser, symmetry, onion skin, straightening, clear the page': 'Más herramientas: guías, estabilizador, simetría, papel cebolla, enderezado, limpiar la página',
  'Export with layers (OpenRaster, for Krita or GIMP)': 'Exportar con capas (OpenRaster, para Krita o GIMP)',
  'Response': 'Respuesta',
  'Soft: a light touch already gives a thick line. Firm: it takes a hard press.': 'Suave: un toque ligero ya da una línea gruesa. Firme: hace falta presionar fuerte.',
  'Tilt thickens': 'La inclinación engrosa',
  'A pen that reports how far it leans draws thicker lines when held flat, like the side of a pencil.': 'Un lápiz que informa de cuánto se inclina dibuja líneas más gruesas cuando se sostiene plano, como el lado de un lápiz.',
  'Button on the side of the pen (held down)': 'Botón en el lateral del lápiz (mantenido pulsado)',
  'A finger': 'Un dedo',
  'Once the pen has been used, fingers only scroll and zoom, so that a resting hand does not write.': 'Una vez usado el lápiz, los dedos solo desplazan y amplían, para que una mano apoyada no escriba.',
  'Fingers never write; only the pen (or a mouse) does.': 'Los dedos nunca escriben; solo escribe el lápiz (o un ratón).',
  'Fingers write too, also when a pen is in use.': 'Los dedos también escriben, incluso cuando hay un lápiz en uso.',
  'Show a ring where the pen hovers': 'Mostrar un anillo donde pasa el lápiz sin tocar',
  'As big as the line it would draw.': 'Tan grande como la línea que dibujaría.',
  'Locked note': 'Nota bloqueada',
  'Encrypted note': 'Nota cifrada',
  'Passphrase': 'Frase de contraseña',
  'Passcode': 'Código de acceso',
  'That is not the passphrase.': 'Esa no es la frase de contraseña.',
  'That is not the passcode.': 'Ese no es el código de acceso.',
  'Show': 'Mostrar',
  'Hide': 'Ocultar',
  'Unlock': 'Desbloquear',
  'Unlock the note': 'Desbloquear la nota',
  'Use fingerprint or face': 'Usar huella o rostro',
  'Lock this note': 'Bloquear esta nota',
  'Lock this note...': 'Bloquear esta nota...',
  'Use at least 6 characters.': 'Usa al menos 6 caracteres.',
  'Use at least 4 characters.': 'Usa al menos 4 caracteres.',
  'The two entries are not the same.': 'Las dos entradas no son iguales.',
  'Keeps the note out of sight: its title is hidden and it asks for the passcode to open. The content is stored as usual, so this does not protect against someone who reads the files of the app.': 'Mantiene la nota fuera de la vista: su título queda oculto y pide el código de acceso para abrirse. El contenido se guarda como de costumbre, así que esto no protege frente a alguien que lea los archivos de la aplicación.',
  'Encrypts the whole note, its title too, with a passphrase. Nothing of it is stored in plain, except while it is open. If you forget the passphrase, the note is lost for good.': 'Cifra toda la nota, también su título, con una frase de contraseña. Nada de ella se guarda en claro, salvo mientras está abierta. Si olvidas la frase de contraseña, la nota se pierde para siempre.',
  'Encrypted': 'Cifrada',
  'Once more': 'Una vez más',
  'Open with fingerprint or face': 'Abrir con huella o rostro',
  "Keeps the secret in this device's keystore, to be given by the device.": 'Guarda el secreto en el almacén de claves de este dispositivo, que lo entrega el propio dispositivo.',
