  'The passage has few of the words of the statement: it may say it differently, or not at all.': 'El pasaje tiene pocas de las palabras de la afirmación: puede decirlo de otra manera, o no decirlo.',
  'Statements with no source named: {n}': 'Afirmaciones sin fuente citada: {n}',
  'This answer names no passage of your notes: it may come from the model, not from them.': 'Esta respuesta no cita ningún pasaje de tus notas: puede venir del modelo, no de ellas.',
  'Named, but not among what was read': 'Citado, pero no entre lo que se leyó',
  'p.': 'p.',
  'New event': 'Nuevo evento',
  'Put tasks on a calendar': 'Poner tareas en un calendario',
  'Ask your notes': 'Pregunta a tus notas',
  'Ask anything: the notes that fit your question are found first, then the passages in them that answer it.': 'Pregunta lo que quieras: primero se encuentran las notas que encajan con tu pregunta, y luego los pasajes de ellas que la responden.',
  'What did I write about deadlines?': '¿Qué escribí sobre las fechas límite?',
  'Summarize my latest notes': 'Resume mis últimas notas',
  'Where did I note something about exams?': '¿Dónde anoté algo sobre exámenes?',
  'There is nothing to read yet.': 'Todavía no hay nada que leer.',
  'This device has no speech program (install speech-dispatcher or espeak-ng).': 'Este dispositivo no tiene programa de voz (instala speech-dispatcher o espeak-ng).',
  'Getting the voice ready... (press to stop)': 'Preparando la voz... (pulsa para parar)',
  'The speech engine of this device did not take the text (is a voice installed?).': 'El motor de voz de este dispositivo no aceptó el texto (¿hay una voz instalada?).',
  'The speech engine of this device did not start (is a voice installed in the system settings?).': 'El motor de voz de este dispositivo no arrancó (¿hay una voz instalada en los ajustes del sistema?).',
  'The speech program made no sound.': 'El programa de voz no produjo sonido.',
  'This device has no working speech engine. Install one (for example eSpeak NG or SherpaTTS from F-Droid) and choose it in the system settings under Text-to-speech.': 'Este dispositivo no tiene un motor de voz que funcione. Instala uno (por ejemplo eSpeak NG o SherpaTTS desde F-Droid) y elígelo en los ajustes del sistema, en Texto a voz.',
  'Summary, presentation, quiz...': 'Resumen, presentación, cuestionario...',
  'What are the key terms and what do they mean?': '¿Cuáles son los términos clave y qué significan?',
  'What is unclear or missing?': '¿Qué no está claro o falta?',
  'Make something from this note': 'Crear algo a partir de esta nota',
  'It is kept with the note, so it is made only once.': 'Se guarda con la nota, así que se crea una sola vez.',
  'What the AI made of this note, and what it can make': 'Lo que la IA ha sacado de esta nota y lo que puede hacer con ella',
  'Cards to learn the note by, one question each.': 'Tarjetas para estudiar la nota, una pregunta cada una.',
  '{name}: page {n}': '{name}: página {n}',
  'Go to the page': 'Ir a la página',
  'Leave this profile?': '¿Salir de este perfil?',
  'This device stops syncing and forgets the other devices. The notes on it stay. The other devices keep the profile.': 'Este dispositivo deja de sincronizarse y olvida los demás dispositivos. Las notas que tiene se quedan. Los demás dispositivos conservan el perfil.',
  'Leave this profile': 'Salir de este perfil',
  'Sync profile': 'Perfil de sincronización',
  'Use Notation on several devices as one person: the same id and name, the same notes and folders, the same settings. The devices connect directly to each other; the signalling server only introduces them.': 'Usa Notation en varios dispositivos como una sola persona: el mismo ID y nombre, las mismas notas y carpetas, los mismos ajustes. Los dispositivos se conectan directamente entre sí; el servidor de señalización solo los presenta.',
  'Add a device': 'Añadir un dispositivo',
  'Use a link from another device': 'Usar un enlace desde otro dispositivo',
  'Name of this device': 'Nombre de este dispositivo',
  'No other device yet. Add one with a link.': 'Todavía no hay otro dispositivo. Añade uno con un enlace.',
  'Syncing...': 'Sincronizando...',
  'Online': 'En línea',
  'Not online': 'Sin conexión',
  'synced {when}': 'sincronizado {when}',
  'Take this device out of the profile': 'Quitar este dispositivo del perfil',
  'Looking for your other devices...': 'Buscando tus otros dispositivos...',
  'Keep my devices in sync automatically': 'Mantener mis dispositivos sincronizados automáticamente',
  'Done: the device is part of your profile now.': 'Listo: el dispositivo ya forma parte de tu perfil.',
  'On the other device open Notation, go to Settings → Sync profile → "Use a link from another device" (or the first screen of the app) and enter this link:': 'En el otro dispositivo abre Notation, ve a Ajustes → Perfil de sincronización → «Usar un enlace desde otro dispositivo» (o la primera pantalla de la aplicación) e introduce este enlace:',
  'Notation: add a device': 'Notation: añadir un dispositivo',
  'The link holds the secret of your profile: send it only to yourself. It works for ten minutes, and a device in it still has to be let in here.': 'El enlace contiene el secreto de tu perfil: envíalo solo a ti mismo. Funciona diez minutos, y un dispositivo que lo use tiene que ser aceptado aquí.',
  '{name} wants to join your profile': '{name} quiere unirse a tu perfil',
  'Is this the code on that device?': '¿Es este el código que aparece en ese dispositivo?',
  'No, that is not my device': 'No, ese no es mi dispositivo',
  'Yes, let it in': 'Sí, dejarlo entrar',
  'That is not a link to add a device.': 'Ese no es un enlace para añadir un dispositivo.',
  'Done: this device is part of the profile now. Its notes, folders and settings are being brought together.': 'Listo: este dispositivo ya forma parte del perfil. Sus notas, carpetas y ajustes se están uniendo.',
  'This code must be the same on the other device:': 'Este código debe ser el mismo en el otro dispositivo:',
  'If it differs, press Cancel: someone else may be in the way.': 'Si es distinto, pulsa Cancelar: puede que alguien esté interfiriendo.',
  'This device takes over the id and name of that profile. Its own notes stay and are brought together with the others.': 'Este dispositivo toma el ID y el nombre de ese perfil. Sus propias notas se conservan y se unen con las demás.',
  'Looking for the device that made the link...': 'Buscando el dispositivo que creó el enlace...',
  'Waiting for the other device to say yes': 'Esperando a que el otro dispositivo diga que sí',
  'There is no signalling server: set one in the live collaboration settings.': 'No hay servidor de señalización: configura uno en los ajustes de colaboración en vivo.',
  'The device that made the link was not found. Is it online, and is its link still on offer?': 'No se encontró el dispositivo que creó el enlace. ¿Está en línea, y sigue disponible su enlace?',
  'The signalling server could not be reached: {error}': 'No se pudo contactar con el servidor de señalización: {error}',
  'The connection to the other device was lost': 'Se perdió la conexión con el otro dispositivo',
  'The other device did not answer': 'El otro dispositivo no respondió',
  'The other device did not follow the protocol': 'El otro dispositivo no siguió el protocolo',
  'The other device runs a different version of the sync': 'El otro dispositivo usa otra versión de la sincronización',
  'The other device did not say who it is': 'El otro dispositivo no dijo quién es',
  'The other devices have another key for this device than the one it signs with, so they refuse it. Sign out of the profile on this device and sign in again.': 'Los otros dispositivos tienen para este otro clave distinta de la que usa para firmar, así que lo rechazan. Cierra sesión en el perfil en este dispositivo y vuelve a iniciarla.',
  'The key of the other device is not the one that was accepted': 'La clave del otro dispositivo no es la que se aceptó',
  'The other device could not prove who it is': 'El otro dispositivo no pudo demostrar quién es',
  'Comparing the devices...': 'Comparando los dispositivos...',
  'This device was removed from the profile': 'Este dispositivo se quitó del perfil',
  'The other device was removed from the profile': 'El otro dispositivo se quitó del perfil',
  'Looking at what changed...': 'Revisando qué ha cambiado...',
  'Sending notes...': 'Enviando notas...',
  'Receiving...': 'Recibiendo...',
  'A new device asks to join': 'Un dispositivo nuevo pide unirse',
  'You did not let the new device in': 'No dejaste entrar al dispositivo nuevo',
  'The other device did not let this one in': 'El otro dispositivo no dejó entrar a este',
  'This device is not one of this profile (add it with the link from a device of the profile)': 'Este dispositivo no es de este perfil (añádelo con el enlace de un dispositivo del perfil)',
  'from before the sync': 'de antes de la sincronización',
  'The server did not accept this device': 'El servidor no aceptó este dispositivo',
  'No connection could be made to the other device. Networks that block direct connections need a TURN server.': 'No se pudo conectar con el otro dispositivo. Las redes que bloquean las conexiones directas necesitan un servidor TURN.',
  'Already use Notation on another device?': '¿Ya usas Notation en otro dispositivo?',
  'Sync this device with it: the same id and name, notes, folders and settings.': 'Sincroniza este dispositivo con él: mismo ID y nombre, notas, carpetas y ajustes.',
  'Use a link from that device': 'Usar un enlace de ese dispositivo',
  'Online status not known': 'Estado de conexión desconocido',
  'This device is not in the meeting room, so it cannot see which of your other devices are online. Turn on the automatic sync below, or press "Sync now" on both devices.': 'Este dispositivo no está en la sala de reuniones, así que no puede ver cuáles de tus otros dispositivos están en línea. Activa la sincronización automática de abajo, o pulsa «Sincronizar ahora» en ambos dispositivos.',
  'Look for my other devices from time to time': 'Buscar mis otros dispositivos de vez en cuando',
  'When the app starts, when it comes to the front and every ten minutes, this device joins the meeting room for a minute and syncs if another device of yours is there. The server only learns of these short visits. Two devices that both only look from time to time meet only when their visits overlap; one that stays connected is always found.': 'Al iniciar la aplicación, al pasar a primer plano y cada diez minutos, este dispositivo entra en la sala de reuniones durante un minuto y se sincroniza si otro de tus dispositivos está allí. El servidor solo conoce estas visitas breves. Dos dispositivos que solo buscan de vez en cuando se encuentran solo si sus visitas coinciden; uno que se mantiene conectado siempre se encuentra.',
  'If it differs, say so: someone else may be in the way. Nothing of the other device is taken over until you say it is the same.': 'Si es distinto, dilo: puede que alguien esté interfiriendo. No se toma nada del otro dispositivo hasta que confirmes que es el mismo.',
  'It is different': 'Es distinto',
  'It is the same': 'Es el mismo',
  'The codes were not the same, so this device was not added': 'Los códigos no coincidían, así que este dispositivo no se añadió',
  'The other device did not keep to what it first said': 'El otro dispositivo no se mantuvo en lo que dijo al principio',
  'Stop reading': 'Dejar de leer',
  'Read the note aloud': 'Leer la nota en voz alta',
  'The event must end after it starts.': 'El evento debe terminar después de que empiece.',
  'Notes': 'Notas',
  'Tasks on a calendar': 'Tareas en un calendario',
  'A task with a day can also be put on a calendar as an all-day event, so that it shows up in the calendar app of the phone or of the server. It goes again when the task is done or deleted.': 'Una tarea con fecha también se puede poner en un calendario como evento de todo el día, para que aparezca en la aplicación de calendario del teléfono o del servidor. Se quita de nuevo cuando la tarea se completa o se borra.',
  'There is no calendar to put them on: connect a server or turn on a calendar of the phone first (both must allow writing).': 'No hay calendario donde ponerlas: conecta primero un servidor o activa un calendario del teléfono (ambos deben permitir escribir).',
  'Not on a calendar': 'No está en un calendario',
  'Only the tasks that were made by an automation or found in a note': 'Solo las tareas creadas por una automatización o encontradas en una nota',
  'What the AI can make of this note': 'Lo que la IA puede sacar de esta nota',
  'Starting...': 'Iniciando...',
  'There is nothing to make a graph of yet: the notes have no text.': 'Todavía no hay nada de lo que hacer un grafo: las notas no tienen texto.',
  'Graph': 'Grafo',
  'Facts': 'Datos',
  'This graph was made before the sentence model was installed, so its topics follow shared words. Make it again to use the model.': 'Este grafo se hizo antes de instalar el modelo de frases, así que sus temas siguen las palabras compartidas. Vuelve a hacerlo para usar el modelo.',
  'No sentence model is installed: topics will follow shared words, not meaning (Settings, AI and models).': 'No hay ningún modelo de frases instalado: los temas seguirán las palabras compartidas, no el significado (Ajustes, IA y modelos).',
  'Name the topics with the AI model': 'Nombrar los temas con el modelo de IA',
