  'Open the note at the page': 'Abrir la nota en la página',
  'The graph of facts shows what your notes say, grouped by topic. Making it reads all notes, so it is not made on its own.': 'El grafo de datos muestra lo que dicen tus notas, agrupado por tema. Al hacerlo se leen todas las notas, así que no se hace por sí solo.',
  'The graph of notes shows which notes belong together and which link to each other. It is not made on its own.': 'El grafo de notas muestra qué notas van juntas y cuáles se enlazan entre sí. No se hace por sí solo.',
