  'Or scan this code with the camera of the other device.': 'O escanea este código con la cámara del otro dispositivo.',
  'Scan the code': 'Escanear el código',
  'Point the camera at the code that "Add a device" shows on the other device.': 'Apunta la cámara al código que «Añadir un dispositivo» muestra en el otro dispositivo.',
  'On a device that is already in the profile, go to Settings → Sync profile → "Add a device". Scan the code it shows or paste the link:': 'En un dispositivo que ya está en el perfil, ve a Ajustes → Perfil de sincronización → «Añadir un dispositivo». Escanea el código que muestra o pega el enlace:',
  'Writing the facts needs an AI model: set one up in the Settings (on this device, or a service), or choose another one with the arrows above.': 'Escribir los datos necesita un modelo de IA: configura uno en los ajustes (en este dispositivo o en un servicio), o elige otro con las flechas de arriba.',
