  'No account for the chosen service on this device yet: connect it in the Settings, or let it come from your other device when they sync directly.': 'Todavía no hay cuenta para el servicio elegido en este dispositivo: conéctala en los ajustes, o que llegue desde tu otro dispositivo al sincronizar directamente.',
  'Syncing through {service}...': 'Sincronizando a través de {service}...',
  'One change taken in': 'Un cambio incorporado',
