  'Your Nextcloud is full.': 'Tu Nextcloud está lleno.',
  'Sync through a cloud folder': 'Sincronizar a través de una carpeta en la nube',
  'No cloud account is connected on this device. Connect one (Nextcloud in the settings under Sync and sharing, or S3, Dropbox or OneDrive under sharing), or sync directly with the device that has one.': 'No hay ninguna cuenta en la nube conectada en este dispositivo. Conecta una (Nextcloud en los ajustes, en Sincronización y uso compartido, o S3, Dropbox o OneDrive en Compartir), o sincroniza directamente con el dispositivo que tiene una.',
  'Service': 'Servicio',
  'not connected': 'no conectado',
  'Folder name': 'Nombre de la carpeta',
  'Every file is sealed with a key from your profile, and the names say nothing. The cloud holds files nobody can read; only your devices can.': 'Cada archivo va cifrado con una clave de tu perfil, y los nombres no dicen nada. La nube guarda archivos que nadie puede leer; solo tus dispositivos pueden.',
  'Not encrypted': 'Sin cifrar',
  'Notes are normal .uninote files and the list is readable text, so you can open them yourself from the cloud. Anyone who can see the folder can read your notes.': 'Las notas son archivos .uninote normales y la lista es texto legible, así que puedes abrirlos tú mismo desde la nube. Quien pueda ver la carpeta puede leer tus notas.',
  'Sync through the folder now': 'Sincronizar ahora a través de la carpeta',
  'last run {when}': 'última ejecución {when}',
  'Before switching branch': 'Antes de cambiar de rama',
