  'e.g. Second approach': 'p. ej. Segundo enfoque',
  'The note is on the branch "{name}" now': 'La nota está ahora en la rama «{name}»',
  'Merge "{from}" into "{into}"?': '¿Fusionar «{from}» en «{into}»?',
  'What was changed on "{from}" since it was branched off (or last merged) is taken into the note. Where both were changed, the note keeps its own. The note as it is now is kept as a version first, so this can be undone.': 'Lo que se cambió en «{from}» desde que se bifurcó (o desde la última fusión) se incorpora a la nota. Cuando se cambió en ambos lados, la nota conserva lo suyo. La nota tal como está ahora se guarda antes como versión, así que se puede deshacer.',
  'Merge': 'Fusionar',
  'Nothing to merge: the note has everything of "{name}" already': 'Nada que fusionar: la nota ya tiene todo lo de «{name}»',
