  'The result is on the clipboard (the text here cannot be changed).': 'El resultado está en el portapapeles (el texto de aquí no se puede cambiar).',
  'Installed {name}. It is off until you switch it on; then its tools ({tools}) are in the menu of selected text, as "{name}: ...".': '{name} instalada. Está desactivada hasta que la actives; entonces sus herramientas ({tools}) están en el menú del texto seleccionado, como «{name}: ...».',
  '{name} is installed and switched on.': '{name} está instalada y activada.',
  'Installed {name}. It is off until you switch it on in Settings > Extensions.': '{name} instalada. Está desactivada hasta que la actives en Ajustes > Extensiones.',
  'One automation was added.': 'Se añadió una automatización.',
  '{n} automations were added.': 'Se añadieron {n} automatizaciones.',
  'They are off.': 'Están desactivadas.',
  'Create with AI': 'Crear con IA',
  'Say what you want in your own words: a tool for selected text, or something that should happen by itself. The AI writes the extension, you read it, and only then is it installed.': 'Di lo que quieres con tus propias palabras: una herramienta para el texto seleccionado, o algo que debe pasar solo. La IA escribe la extensión, tú la lees, y solo después se instala.',
  'e.g. A tool that turns the selected lines into a checklist. Or: when a note has not been opened for a month, add a task to look at it.': 'p. ej. Una herramienta que convierte las líneas seleccionadas en una lista de verificación. O: cuando una nota lleva un mes sin abrirse, añadir una tarea para revisarla.',
  'What is sent to the AI you chose in Settings: the description of the extension API and your request. No notes, no files. With an AI in the cloud that leaves this device.': 'Lo que se envía a la IA elegida en los ajustes: la descripción de la API de extensiones y tu petición. Ni notas ni archivos. Con una IA en la nube, eso sale de este dispositivo.',
  'The AI is writing it...': 'La IA está escribiendo la extensión...',
  'The first try had a problem, the AI tries again: {problem}': 'El primer intento tuvo un problema, la IA lo vuelve a intentar: {problem}',
  'Tools (in the menu of selected text)': 'Herramientas (en el menú del texto seleccionado)',
  'Actions (for automations)': 'Acciones (para las automatizaciones)',
  'The script uses {what}, which the AI had not asked for; it was added.': 'El script usa {what}, que la IA no había pedido; se añadió.',
  'Automations it adds': 'Automatizaciones que añade',
