  'Change it': 'Cambiar',
  'Install (off)': 'Instalar (desactivada)',
  'Install and allow': 'Instalar y permitir',
  'Install puts it in the list switched off and without any permission. Install and allow also switches it on and gives it the permissions above.': 'Instalar la pone en la lista desactivada y sin ningún permiso. Instalar y permitir además la activa y le da los permisos de arriba.',
  'Read the documentation': 'Leer la documentación',
  'Extension documentation': 'Documentación de las extensiones',
  'The documentation could not be loaded.': 'No se pudo cargar la documentación.',
  'Reading the PDFs...': 'Leyendo los PDF...',
  'Study: {topic}': 'Estudiar: {topic}',
  'There are no facts here to study.': 'No hay datos aquí que estudiar.',
  'Studying needs an AI model: set one up in the Settings (on this device, or a service).': 'Estudiar necesita un modelo de IA: configura uno en los ajustes (en este dispositivo o en un servicio).',
  'The AI did not write any usable cards. Try again.': 'La IA no escribió tarjetas utilizables. Inténtalo de nuevo.',
  'The AI did not write any usable questions. Try again.': 'La IA no escribió preguntas utilizables. Inténtalo de nuevo.',
  'The AI did not give a grade. Try sending the answer again.': 'La IA no dio una calificación. Intenta enviar la respuesta otra vez.',
  'The AI writes cards from the facts: a short question on the front, the answer from the facts on the back.': 'La IA escribe tarjetas a partir de los datos: una pregunta corta en el anverso y la respuesta sacada de los datos en el reverso.',
  'The AI is writing...': 'La IA está escribiendo...',
  'The AI writes questions about the facts. You answer in your own words, the AI grades the answer, and questions you know less well come back first.': 'La IA escribe preguntas sobre los datos. Respondes con tus palabras, la IA califica la respuesta, y las preguntas que dominas peor vuelven antes.',
  'Make a quiz': 'Hacer un cuestionario',
  '{done} of {total} mastered': '{done} de {total} dominadas',
  'You have mastered every question.': 'Has dominado todas las preguntas.',
  'Your answer': 'Tu respuesta',
