  'Next question': 'Siguiente pregunta',
  'Make a new quiz': 'Hacer un cuestionario nuevo',
  'Ask something about these facts. The answer rests on the facts alone; when they do not say, the AI tells you so.': 'Pregunta algo sobre estos datos. La respuesta se basa solo en los datos; cuando no dicen nada, la IA te lo indica.',
  'All facts': 'Todos los datos',
  'Roomier text': 'Texto más espaciado',
  'More space between lines, words and letters.': 'Más espacio entre líneas, palabras y letras.',
  'This device is not part of a sync profile yet, so there is nothing to sync through the folder.': 'Este dispositivo todavía no forma parte de un perfil de sincronización, así que no hay nada que sincronizar por la carpeta.',
  'Waiting for the direct sync with your other device to end...': 'Esperando a que termine la sincronización directa con tu otro dispositivo...',
  'The other device does not sync its notes now': 'El otro dispositivo no sincroniza sus notas ahora',
  'Work on a note on two devices at the same time': 'Trabajar en una nota en dos dispositivos a la vez',
  'Share this note with a person': 'Compartir esta nota con una persona',
  'Share this folder with a person': 'Compartir esta carpeta con una persona',
  'Invites someone who has an account at the same cloud service. They see it in their own account and in the app, and can only do what you allow. Changes go both ways. The files are not sealed: the cloud service can read what you share.': 'Invita a alguien que tenga una cuenta en el mismo servicio de nube. La ve en su propia cuenta y en la aplicación, y solo puede hacer lo que permitas. Los cambios van en ambos sentidos. Los archivos no van cifrados: el servicio de nube puede leer lo que compartes.',
  'Can view': 'Puede ver',
  'Can edit': 'Puede editar',
  'Sharing...': 'Compartiendo...',
  'Share': 'Compartir',
  'Stop sharing': 'Dejar de compartir',
  'Accept': 'Aceptar',
  'Look for shares': 'Buscar recursos compartidos',
  'Looking...': 'Buscando...',
  'Remove from the list': 'Quitar de la lista',
  'Shared with people': 'Compartido con personas',
  'Notes and folders you share with people at the same cloud service (Nextcloud), and the ones they share with you. Share from a note (the live button) or from the menu of a folder. What is shared is kept in step in the background. The cloud service can read these files: they are not sealed.': 'Las notas y carpetas que compartes con personas del mismo servicio de nube (Nextcloud), y las que ellas comparten contigo. Comparte desde una nota (el botón en vivo) o desde el menú de una carpeta. Lo compartido se mantiene al día en segundo plano. El servicio de nube puede leer estos archivos: no van cifrados.',
  'Shared with': 'Compartido con',
  'Remove {name}': 'Quitar a {name}',
  'Name or address of the person': 'Nombre o dirección de la persona',
  'Connect a cloud service that can share (Nextcloud) in the settings first.': 'Conecta primero, en los ajustes, un servicio de nube que pueda compartir (Nextcloud).',
  'Where should "{name}" go?': '¿Dónde debe ir «{name}»?',
