  'Share with people...': 'Compartir con personas...',
  'That folder is gone': 'Esa carpeta ya no existe',
  'This device is not part of a sync profile yet.': 'Este dispositivo todavía no forma parte de un perfil de sincronización.',
  'The share was withdrawn. What you have of it stays.': 'Se retiró el recurso compartido. Lo que tienes de él se queda.',
  'The owner removed this. What you have of it stays.': 'El propietario lo quitó. Lo que tienes de él se queda.',
  'This is not a share from Notation, or from a newer version of it.': 'Esto no es un recurso compartido de Notation, ni de una versión más nueva.',
  'You have this {what} already, and not from this share. Delete it here first to take the share in.': 'Ya tienes este {what}, y no viene de este recurso compartido. Bórralo aquí primero para aceptar el recurso compartido.',
  'note': 'nota',
  'folder': 'carpeta',
  'The Nextcloud allows only a few new shares in a short time. Try again in a few minutes.': 'Nextcloud solo permite unos pocos recursos compartidos nuevos en poco tiempo. Inténtalo de nuevo en unos minutos.',
  'This Nextcloud does not offer sharing with people.': 'Este Nextcloud no ofrece compartir con personas.',
  'The Nextcloud did not share the folder.': 'Nextcloud no pudo compartir la carpeta.',
  'The Nextcloud did not accept the share.': 'Nextcloud no aceptó el recurso compartido.',
  'Allow sharing with people in the OneDrive settings first (it needs access to all your files).': 'Primero permite compartir con personas en los ajustes de OneDrive (necesita acceso a todos tus archivos).',
  'Sign in to OneDrive again, so that it can be allowed to share.': 'Vuelve a iniciar sesión en OneDrive, para que pueda permitir compartir.',
  'OneDrive does not allow sharing with this person here (an administrator can forbid it for work and school accounts).': 'OneDrive no permite compartir con esta persona aquí (un administrador puede prohibirlo en cuentas de trabajo y de centro educativo).',
  'OneDrive says to wait a little. Try again in a few minutes.': 'OneDrive pide esperar un poco. Inténtalo de nuevo en unos minutos.',
  'The shared folder is not on your OneDrive (any more).': 'La carpeta compartida ya no está (o nunca estuvo) en tu OneDrive.',
  'Shared with Notation. Open the link in the invitation, or add it in the app: Settings, Sync and sharing.': 'Compartido con Notation. Abre el enlace de la invitación, o añádelo en la aplicación: Ajustes, Sincronización y uso compartido.',
  'OneDrive did not share the folder.': 'OneDrive no compartió la carpeta.',
  'This is not a link to a share.': 'Esto no es un enlace a un recurso compartido.',
  'This link does not open a shared folder for you. Are you signed in with the account that was invited?': 'Este enlace no te abre ninguna carpeta compartida. ¿Has iniciado sesión con la cuenta invitada?',
  'This is not a share from Notation.': 'Esto no es un recurso compartido de Notation.',
  'You have this share already.': 'Ya tienes este recurso compartido.',
  'Allow sharing with people in the Dropbox settings first (it needs a Dropbox app with access to the whole Dropbox).': 'Primero permite compartir con personas en los ajustes de Dropbox (necesita una app de Dropbox con acceso a todo Dropbox).',
  'Sign in to Dropbox again, so that it can be allowed to share.': 'Vuelve a iniciar sesión en Dropbox, para que pueda permitir compartir.',
  'Dropbox says to wait a little. Try again in a few minutes.': 'Dropbox pide esperar un poco. Inténtalo de nuevo en unos minutos.',
  'This Dropbox app is not allowed to share. It has to be registered with access to the whole Dropbox, and with the sharing permissions.': 'Esta app de Dropbox no tiene permiso para compartir. Tiene que estar registrada con acceso a todo Dropbox y con los permisos de compartir.',
  'Your Dropbox e-mail address has to be verified before you can share.': 'Tu dirección de correo de Dropbox debe verificarse antes de poder compartir.',
  'Your Dropbox plan does not allow sharing with this many people.': 'Tu plan de Dropbox no permite compartir con tantas personas.',
  'The shared folder is not on your Dropbox (any more).': 'La carpeta compartida ya no está (o nunca estuvo) en tu Dropbox.',
  'Dropbox did not do it.': 'Dropbox no lo hizo.',
  'Dropbox did not share the folder.': 'Dropbox no compartió la carpeta.',
  'Dropbox is slow to share the folder. Try again in a moment.': 'Dropbox tarda en compartir la carpeta. Inténtalo de nuevo en un momento.',
  'Shared with Notation. Accept it in your Dropbox, then it is listed in the app: Settings, Sync and sharing.': 'Compartido con Notation. Acéptalo en tu Dropbox y luego aparecerá en la aplicación: Ajustes, Sincronización y uso compartido.',
  'Dropbox did not accept the share.': 'Dropbox no aceptó el recurso compartido.',
  'Link copied. Send it to {name}: they add it under Settings, Sync and sharing.': 'Enlace copiado. Envíaselo a {name}: lo añade en Ajustes, Sincronización y uso compartido.',
  'Copy the link to send to {name}': 'Copiar el enlace para enviar a {name}',
  'A link to a share (OneDrive)': 'Un enlace a un recurso compartido (OneDrive)',
  '"{name}" is shared with you by {who}. Take it in under Settings, Sync and sharing.': '«{name}» lo comparte contigo {who}. Acéptalo en Ajustes, Sincronización y uso compartido.',
  'Also allow sharing with people': 'Permitir también compartir con personas',
  'Sharing a folder with someone, and opening what they share with you, needs access to all your OneDrive files, not just the folder of the app. Changing this signs you out: sign in again afterwards. (Settings, Shared with people)': 'Compartir una carpeta con alguien, y abrir lo que comparte contigo, necesita acceso a todos tus archivos de OneDrive, no solo a la carpeta de la aplicación. Cambiar esto cierra tu sesión: vuelve a iniciarla después. (Ajustes, Compartido con personas)',
  'Sharing a folder with someone, and opening what they share with you, only works with a Dropbox app that has access to the whole Dropbox (not the app folder alone), and the sharing permissions. Turn this on only if the app key above is such an app. Changing this signs you out: sign in again afterwards.': 'Compartir una carpeta con alguien, y abrir lo que comparte contigo, solo funciona con una app de Dropbox que tenga acceso a todo Dropbox (no solo a la carpeta de la app), y con los permisos de compartir. Actívalo solo si la clave de app de arriba es una app así. Cambiar esto cierra tu sesión: vuelve a iniciarla después.',
