  'This note has no text boxes or written document to translate. Handwriting is not translated.': 'Esta nota no tiene cuadros de texto ni documento escrito que traducir. La escritura a mano no se traduce.',
  'The text of the PDF is rewritten in its translation, page by page. Longer lines are set smaller, and a line that cannot be shown stays as it was. A version of the note is kept first, and the change can be taken back with Undo.': 'El texto del PDF se reescribe en su traducción, página a página. Las líneas más largas se componen más pequeñas, y una línea que no se puede mostrar se queda como estaba. Antes se guarda una versión de la nota, y el cambio se puede deshacer con Deshacer.',
  'The {n} texts in this note are replaced by their translation, in place. A version of the note is kept first, and the change can be taken back with Undo.': 'Los {n} textos de esta nota se sustituyen por su traducción, en el mismo sitio. Antes se guarda una versión de la nota, y el cambio se puede deshacer con Deshacer.',
