  'Drawings stay shapes you can edit in a vector program; layers become named groups. Text boxes and pictures are pictures in the file.': 'Los dibujos siguen siendo formas editables en un programa vectorial; las capas se convierten en grupos con nombre. Las cajas de texto y las imágenes son imágenes en el archivo.',
