  'Alignment lines': 'Líneas de alineación',
  'Lines that show where a text box, picture or shape you are moving lines up with the others on the page (or the middle and edges of the page), and let it fall into place. Hold Alt to move freely.': 'Las líneas que muestran cuándo una caja de texto, imagen o forma que mueves se alinea con las demás de la página (o con el centro y los bordes de la página), y la dejan encajar. Mantén Alt para moverla libremente.',
  'Save the pages of a note as pictures (PNG) in a size for the web, a screen, print, a post, a slide or a story, with the background left out if you like.': 'Guarda las páginas de una nota como imágenes (PNG) en un tamaño para la web, una pantalla, impresión, una publicación, una diapositiva o una historia, con el fondo quitado si quieres.',
