  'like "{text}"': 'como «{text}»',
  'Connect an AI agent': 'Conectar un agente de IA',
  'An AI agent on this computer (Claude Code, an editor with AI, any program that speaks the Model Context Protocol) can then find, read and write your notes, folders, tags and tasks. It connects to this app on this computer only, with the token below. Locked notes are never available to it, and it cannot delete a note for good. Every change to a note keeps a version of it before and after, which you can bring back. What the agent reads goes to the AI service it belongs to: connect only agents you trust with your notes.': 'Un agente de IA en este ordenador (Claude Code, un editor con IA, cualquier programa que hable el Model Context Protocol) puede entonces encontrar, leer y escribir tus notas, carpetas, etiquetas y tareas. Se conecta solo a esta aplicación en este ordenador, con el token de abajo. A las notas bloqueadas nunca tiene acceso, y no puede borrar una nota para siempre. Cada cambio en una nota guarda una versión antes y después, que puedes recuperar. Lo que lee el agente va al servicio de IA al que pertenece: conecta solo agentes en los que confíes con tus notas.',
