  'Describe a rule': 'Describe una regla',
  '{n} minutes before it starts': '{n} minutos antes de empezar',
  'Trigger {n}': 'Disparador {n}',
  'The note gets a star': 'La nota recibe una estrella',
  'The page becomes a source, to cite with [@key]': 'La página pasa a ser una fuente, para citar con [@clave]',
  'The note is listed on the dashboard, with the question what to do about it': 'La nota aparece en el panel, con la pregunta de qué hacer con ella',
  'The summary is a text box under the rest of the last page': 'El resumen es un cuadro de texto debajo del resto de la última página',
  'The outline is a text box under the rest of the last page': 'El esquema es un cuadro de texto debajo del resto de la última página',
  'Only notes without a title are named': 'Solo se nombran las notas sin título',
  'About {n} flashcards from the note, kept for review': 'Unas {n} tarjetas de estudio sacadas de la nota, guardadas para repasar',
  'Half a minute after the last change': 'Medio minuto después del último cambio',
  'What this rule did': 'Lo que hizo esta regla',
  'There are no templates here.': 'No hay plantillas aquí.',
  'Choose a template': 'Elegir una plantilla',
  'No template (a blank note)': 'Ninguna plantilla (una nota en blanco)',
  'A further step': 'Un paso más',
  'Which trigger': 'Qué disparador',
  'Bind a key to "Run the automations of trigger 1" in the settings of the shortcuts, or set the side button of the pen to it (Settings, pen)': 'Asocia una tecla a «Ejecutar las automatizaciones del disparador 1» en los ajustes de atajos, o pon el botón lateral del lápiz en ella (Ajustes, lápiz)',
  'Minutes before it starts': 'Minutos antes de empezar',
  'Looked at every minute while the app runs; each event once': 'Se revisa cada minuto mientras la aplicación se ejecuta; cada evento una sola vez',
  'A note whose title is empty or "Untitled Note" is named after what it says: the language model writes a short title if it is installed (Settings), else the first line is used when it is short enough. A note that has a title is never changed.': 'Una nota cuyo título está vacío o es «Nota sin título» se nombra según lo que dice: el modelo de lenguaje escribe un título corto si está instalado (Ajustes); si no, se usa la primera línea si es lo bastante corta. Una nota que ya tiene título nunca se cambia.',
  'The assistant reads the text of the note and writes flashcards from it, which are kept for review (Flashcards, spaced repetition). A question that is kept already is not added again. Needs the assistant; a model on this device takes a minute or so.': 'El asistente lee el texto de la nota y escribe tarjetas de estudio a partir de él, que se guardan para repasar (Tarjetas de estudio, repetición espaciada). Una pregunta que ya está guardada no se vuelve a añadir. Necesita el asistente; un modelo en este dispositivo tarda un minuto más o menos.',
  'About how many cards': 'Aproximadamente cuántas tarjetas',
  '{n} is how many cards are due. One task a day, today, while there are cards due': '{n} es el número de tarjetas que toca repasar. Una tarea al día, hoy, mientras haya tarjetas que repasar',
  'Then also, one after the other': 'Después también, una tras otra',
  'Take this step out': 'Quitar este paso',
  'Add a step': 'Añadir un paso',
  'The steps run in the background, one after the other. Each can use {result}, what the one before said, in its text; a step that cannot do its work ends the chain.': 'Los pasos se ejecutan en segundo plano, uno tras otro. Cada uno puede usar {result}, lo que dijo el anterior, en su texto; un paso que no puede hacer su trabajo termina la cadena.',
  'Dropbox needs an app of your own: create one at dropbox.com/developers/apps ("Scoped access", "App folder"), allow files.content.write, files.content.read, files.metadata.read and sharing.write, add the redirect URI notation://oauth/dropbox, and enter its app key here.': 'Dropbox necesita una aplicación propia: créala en dropbox.com/developers/apps («Scoped access», «App folder»), permite files.content.write, files.content.read, files.metadata.read y sharing.write, añade la URI de redirección notation://oauth/dropbox e introduce aquí su clave de aplicación.',
  '"{address}" is not the address of a relay. Use something like turn:turn.example.org:3478': '«{address}» no es la dirección de un relé. Usa algo como turn:turn.example.org:3478',
  'Notation could not start': 'Notation no pudo arrancar',
  'Nothing was deleted. Close the app and open it again; if this keeps happening, make sure the device has free storage and that this is not an older version of the app than the one that last ran.': 'No se borró nada. Cierra la aplicación y vuelve a abrirla; si sigue pasando, comprueba que el dispositivo tenga espacio libre y que no sea una versión más antigua de la aplicación que la última que se ejecutó.',
  'View': 'Ver',
  'The quick brown fox jumps over the lazy dog.': 'El veloz murciélago hindú comía feliz cardillo y kiwi.',
  'Sync problem': 'Problema de sincronización',
