  'Arrange the toolbars': 'Organizar las barras de herramientas',
  'Record the sound while you write: each line is tied to the moment it was written': 'Grabar el sonido mientras escribes: cada línea queda ligada al momento en que se escribió',
  'The microphone is not allowed (see the settings of the system)': 'No está permitido el micrófono (ver los ajustes del sistema)',
