  'Reading the handwriting: {n} left': 'Leyendo la escritura a mano: quedan {n}',
  'Kept the sound with 1 line tied to its moment': 'Sonido guardado con 1 línea ligada a su momento',
  'Kept the sound with {n} lines tied to their moments': 'Sonido guardado con {n} líneas ligadas a sus momentos',
  'Lecture {date}': 'Lectura {date}',
  'Play the sound from when this was written': 'Reproducir el sonido desde el momento en que se escribió esto',
  'The sound of this line is not there any more': 'El sonido de esta línea ya no está',
  'Keep this mistake as a flashcard': 'Guardar este error como tarjeta de estudio',
  'Kept it as a flashcard, to ask again later': 'Guardado como tarjeta de estudio, para preguntarla más tarde',
  'This mistake is a flashcard already': 'Este error ya es una tarjeta de estudio',
  'Edit text': 'Editar texto',
  'Smaller': 'Más pequeño',
  'Bigger': 'Más grande',
  'Rotate': 'Girar',
  'Change the toolbar profile': 'Cambiar el perfil de barras de herramientas',
  'Nothing here. Move a section over from the other bar.': 'Aquí no hay nada. Mueve una sección desde la otra barra.',
  'Profiles': 'Perfiles',
  'A profile keeps an arrangement of the toolbars with the tools it uses, so you can change between ways of working (drawing, maths...) in one tap.': 'Un perfil guarda una disposición de las barras de herramientas con las herramientas que usa, para cambiar de forma de trabajar (dibujo, mates...) con un solo toque.',
  'New profile': 'Perfil nuevo',
  'Tools in this profile': 'Herramientas de este perfil',
  'The tools that are switched on in the settings. One that is off there is off in every profile.': 'Las herramientas activadas en los ajustes. Una que esté desactivada allí lo está en todos los perfiles.',
  '(new)': '(nuevo)',
  'This replaces version {version}.': 'Esto reemplaza la versión {version}.',
  'It is installed switched off and without any permission. You switch it on and give it these in Settings.': 'Se instala desactivado y sin ningún permiso. Lo activas y le das estos en los ajustes.',
  'The note was closed': 'La nota se cerró',
  'Could not save the pictures: {error}': 'No se pudieron guardar las imágenes: {error}',
  'Saved 1 picture in {dir}': '1 imagen guardada en {dir}',
  'Saved {n} pictures in {dir}': '{n} imágenes guardadas en {dir}',
  '{n} fact': '{n} dato',
  '{n} facts': '{n} datos',
  'Possible contradictions': 'Posibles contradicciones',
  'Facts that disagree': 'Datos que no coinciden',
  'These facts come from different notes, are about the same thing and give different numbers. One of them may be out of date, or both may be right in their own place.': 'Estos datos vienen de notas distintas, tratan de lo mismo y dan cifras diferentes. Uno de ellos puede estar desfasado, o ambos pueden ser correctos en su contexto.',
  'Says something else in {note}': 'Dice otra cosa en {note}',
  'another note': 'otra nota',
  'Do you use these one at a time?': '¿Usas estos por separado?',
  'Then give each its own toolbar profile: one tap changes the toolbars to the tools of that use only (drawing without the maths tools, and the other way around). All of them stay available; you can change the profiles whenever you like.': 'Entonces dale a cada uno su propio perfil de barras de herramientas: un toque cambia las barras a las herramientas de ese uso solo (dibujo sin las de mates, y al revés). Todas siguen disponibles; puedes cambiar los perfiles cuando quieras.',
  'Make a profile for each: {names}': 'Crear un perfil para cada uno: {names}',
  'Each toolbar profile uses its own share of these tools; what you switch off here is off in all of them.': 'Cada perfil de barras de herramientas usa su parte de estas herramientas; lo que desactives aquí queda desactivado en todos.',
  'Create': 'Crear',
  'No automation is set for trigger {n} (see Automations)': 'No hay ninguna automatización para el disparador {n} (ver Automatizaciones)',
  'Trigger {trigger}: ran 1 automation': 'Disparador {trigger}: se ejecutó 1 automatización',
  'Trigger {trigger}: ran {n} automations': 'Disparador {trigger}: se ejecutaron {n} automatizaciones',
  'Menu': 'Menú',
  'PDF sharpness': 'Nitidez de los PDF',
  'The most PDF pages are drawn at. On screen a page is drawn as sharp as the screen shows it, up to this; zoomed in, the part on screen is drawn sharper. Pictures of pages that are exported use it as it is. Higher is sharper but uses more memory and loads slower. Automatic picks 250 dpi on a device with plenty of memory and 200 dpi on others. It applies to PDFs opened from now on.': 'A qué resolución se dibujan la mayoría de las páginas PDF. En pantalla, una página se dibuja tan nítida como la pantalla la muestra, hasta este valor; con zoom, la parte visible se dibuja más nítida. Las imágenes de las páginas exportadas lo usan tal cual. Más alto es más nítido pero usa más memoria y carga más despacio. Automático elige 250 ppp en un dispositivo con mucha memoria y 200 ppp en los demás. Se aplica a los PDF que se abran desde ahora.',
  'Automatic ({dpi} dpi on this device)': 'Automático ({dpi} ppp en este dispositivo)',
  'QR code': 'Código QR',
  'Plan for an exam': 'Plan para un examen',
  'It could not be looked at.': 'No se pudo revisar.',
  'Say what should happen by itself, in your own words. The assistant writes the rule; you look at it, and at what it would have touched, before it is switched on.': 'Di con tus palabras lo que debe pasar solo. El asistente escribe la regla; tú la revisas, y lo que tocaría, antes de activarla.',
  'For example: when I close a note in Physics, give it the tag lecture': 'Por ejemplo: cuando cierro una nota de Física, ponerle la etiqueta clase',
  'Write the rule': 'Escribir la regla',
  'The assistant could not make a rule of that with what automations can do. Try saying it another way.': 'El asistente no pudo hacer una regla de eso con lo que pueden hacer las automatizaciones. Prueba a decirlo de otra forma.',
  'Looking at what it would touch...': 'Revisando lo que tocaría...',
  'Added: see the list of automations.': 'Añadida: mira la lista de automatizaciones.',
  'Add, switched off': 'Añadir, desactivada',
  'Add and switch on': 'Añadir y activar',
  '{n} line was left out': '{n} línea se dejó fuera',
  '{n} lines were left out': '{n} líneas se dejaron fuera',
  'Folder': 'Carpeta',
  'Relay server (for mobile networks)': 'Servidor de relé (para redes móviles)',
  'Two devices connect to each other directly. On a mobile network, and behind some other networks, that does not work: a relay (a TURN server) then passes the data between them. It sees nothing of it, as everything is sealed. Run your own (coturn, say) or use a service that offers one, and enter its address and the name and password it gave you. This stays on this device; set it on the devices that are on such a network (it does not hurt on the others).': 'Dos dispositivos se conectan directamente entre sí. En una red móvil, y detrás de algunas otras redes, eso no funciona: un relé (un servidor TURN) pasa entonces los datos entre ellos. No ve nada de ellos, porque todo va cifrado. Ejecuta el tuyo (coturn, por ejemplo) o usa un servicio que ofrezca uno, e introduce su dirección y el nombre y la contraseña que te dio. Esto se queda en este dispositivo; ponlo en los dispositivos que estén en esa red (no molesta en los demás).',
  'Relay address': 'Dirección del relé',
  'Password': 'Contraseña',
  'Speech to text': 'Voz a texto',
  'Language spoken': 'Idioma hablado',
  'Find out by listening': 'Averiguar escuchando',
  'Record and write down': 'Grabar y anotar',
  'Use the text': 'Usar el texto',
  'Writing down speech needs a model on this device (about {size} MB). It works without the internet, and nothing you say leaves the device.': 'Anotar la voz necesita un modelo en este dispositivo (unos {size} MB). Funciona sin internet, y nada de lo que dices sale del dispositivo.',
  'New plan': 'Plan nuevo',
  'Say when the exam is. The app works backwards from that day and puts a short session on each day of the calendar, and changes the sessions every day for what you got right.': 'Di cuándo es el examen. La aplicación cuenta hacia atrás desde ese día y pone una sesión corta en cada día del calendario, y cambia las sesiones cada día según lo que hayas acertado.',
  'The exam is today': 'El examen es hoy',
  '{n} day left: the exam is on {day}': 'Queda {n} día: el examen es el {day}',
  '{n} days left: the exam is on {day}': 'Quedan {n} días: el examen es el {day}',
  'No session today': 'Sin sesión hoy',
  '{n} new card does not fit in the time: more minutes a day would help': '{n} tarjeta nueva no cabe en el tiempo: más minutos al día ayudarían',
  '{n} new cards do not fit in the time: more minutes a day would help': '{n} tarjetas nuevas no caben en el tiempo: más minutos al día ayudarían',
  'Delete the plan and its sessions that are still to come': 'Borrar el plan y sus sesiones que aún quedan',
  'New plan for an exam': 'Plan nuevo para un examen',
  'What is the exam?': '¿Cuál es el examen?',
  'Biology': 'Biología',
  'Exam on': 'Examen el',
  'Which cards': 'Qué tarjetas',
  'All my cards': 'Todas mis tarjetas',
  '{n} minute a day': '{n} minuto al día',
  '{n} minutes a day': '{n} minutos al día',
  'No session on': 'Sin sesión el',
  'Make the plan': 'Hacer el plan',
  'Synced': 'Sincronizado',
  'Looking for your other devices. They have to be looking too: press "Sync now" there, or turn on the automatic sync.': 'Buscando tus otros dispositivos. Ellos también tienen que buscar: pulsa «Sincronizar ahora» allí, o activa la sincronización automática.',
  'Better': 'Mejor',
  'Faster': 'Más rápido',
  'Models opened so far': 'Modelos abiertos hasta ahora',
  'This browser gives the page no graphics card (WebGPU): models run on the processor. WebGPU needs https or localhost, and a browser that has it switched on (chrome://gpu shows why not).': 'Este navegador no da a la página ninguna tarjeta gráfica (WebGPU): los modelos se ejecutan en el procesador. WebGPU necesita https o localhost, y un navegador que lo tenga activado (chrome://gpu muestra por qué no).',
  'Timing…': 'Midiendo…',
  'Time the handwriting reader': 'Medir el lector de escritura a mano',
  'Size of the model': 'Tamaño del modelo',
  'Exact ({mb} MB)': 'Exacto ({mb} MB)',
  'Compact ({mb} MB)': 'Compacto ({mb} MB)',
  'Compact is a third smaller and reads about two points less exactly. In a browser it is the one the graphics card can run (WebGPU), and much faster there. Changing it downloads the other file.': 'Compacto pesa un tercio menos y lee unos dos puntos menos exactamente. En un navegador es el que puede ejecutar la tarjeta gráfica (WebGPU), y mucho más rápido allí. Cambiarlo descarga el otro archivo.',
  'Run models on': 'Ejecutar los modelos en',
  'Looking for an accelerator…': 'Buscando un acelerador…',
  'Available on this device: {names}': 'Disponible en este dispositivo: {names}',
  'This device has no accelerator the app can use: models always run on the processor.': 'Este dispositivo no tiene ningún acelerador que la aplicación pueda usar: los modelos siempre se ejecutan en el procesador.',
  'Accelerator when available': 'Acelerador cuando esté disponible',
  'Processor only': 'Solo procesador',
  'Graphics card ({mb} MB)': 'Tarjeta gráfica ({mb} MB)',
  'Small ({mb} MB)': 'Pequeño ({mb} MB)',
  'Full ({mb} MB)': 'Completo ({mb} MB)',
  'Check the accelerator with a small test model': 'Comprobar el acelerador con un modelo de prueba pequeño',
  'Checking…': 'Comprobando…',
  'Not available in the browser.': 'No disponible en el navegador.',
  'Opened on': 'Abierto en',
  'Failed': 'Fallido',
  'differs from the processor by at most {n}': 'difiere del procesador en como mucho {n}',
  'preparing the model for {name} (can take minutes)': 'preparando el modelo para {name} (puede tardar minutos)',
  'preparing the model': 'preparando el modelo',
  'Graphics card is the encoder in 16 bits, for a graphics card runtime (AMD\'s cannot run the 8-bit one): twice the size, much quicker there, reads about as well. Changing it downloads the encoder. Full is the published encoder unchanged, in 32 bits: the largest, reads like the original, and the form a phone\'s accelerator can take most of.': 'La tarjeta gráfica es el codificador en 16 bits, para un entorno de tarjeta gráfica (el de AMD no puede ejecutar el de 8 bits): el doble de grande, mucho más rápido allí, lee casi igual de bien. Cambiarlo descarga el codificador. Completo es el codificador publicado sin cambios, en 32 bits: el más grande, lee como el original, y es la forma que más aceptan los aceleradores de teléfono.',
  'Graphics card is for a graphics card runtime (AMD\'s cannot run the quantised ones): not shrunk, reads like Exact.': 'La tarjeta gráfica es para un entorno de tarjeta gráfica (el de AMD no puede ejecutar los cuantizados): sin reducir, lee como Exacto.',
  'Preparing…': 'Preparando…',
  'Plans can only be made for the "Graphics card" size of the handwriting or the formula model (see their settings), once it is installed.': 'Solo se pueden hacer planes para el tamaño «Tarjeta gráfica» del modelo de escritura a mano o de fórmulas (ver sus ajustes), cuando esté instalado.',
  'Plan for the graphics card': 'Plan para la tarjeta gráfica',
  'Precompile the formula plan': 'Precompilar el plan de fórmulas',
  'Done: the plan is made and kept.': 'Listo: el plan está hecho y guardado.',
  'Formula pictures are always the same size, so there is nothing to pad and one plan to make. The graphics card works it out once (about 2 minutes) and keeps it; until then the first formula can wait.': 'Las imágenes de fórmulas siempre tienen el mismo tamaño, así que no hay nada que rellenar y un solo plan que hacer. La tarjeta gráfica lo calcula una vez (unos 2 minutos) y lo guarda; mientras tanto, la primera fórmula puede esperar.',
  'Precompile picture sizes': 'Precompilar los tamaños de imagen',
  'Handwriting: all {all} picture sizes of this quality have their plan.': 'Escritura a mano: los {all} tamaños de imagen de esta calidad tienen su plan.',
  'Formulas: the plan is made.': 'Fórmulas: el plan está hecho.',
  'Formulas: no plan yet.': 'Fórmulas: todavía sin plan.',
  'Waiting for the block that is being read in the background...': 'Esperando al bloque que se está leyendo en segundo plano...',
  'handwriting': 'escritura a mano',
  'formulas': 'fórmulas',
  'speech': 'voz',
  'search': 'búsqueda',
  'embedding model': 'modelo de embeddings',
  'language model': 'modelo de lenguaje',
  'picture part': 'parte de imagen',
  'text part': 'parte de texto',
  'sound part': 'parte de sonido',
  '{model} ({purpose}): {file}': '{model} ({purpose}): {file}',
  '{model} ({purpose}), {part}: {file}': '{model} ({purpose}), {part}: {file}',
  'processor (CPU)': 'procesador (CPU)',
  'processor (in the browser)': 'procesador (en el navegador)',
  'graphics card ({name})': 'tarjeta gráfica ({name})',
  'accelerator ({name})': 'acelerador ({name})',
  'processor ({name})': 'procesador ({name})',
  'graphics card making a plan': 'tarjeta gráfica haciendo un plan',
  'graphics card': 'tarjeta gráfica',
  'accelerator': 'acelerador',
  'processor': 'procesador',
  'Size {done} of {total} done. Each takes 4 to 5 minutes; the app can be used meanwhile, and what is done is kept.': 'Tamaño {done} de {total} listo. Cada uno tarda de 4 a 5 minutos; la aplicación se puede usar mientras tanto, y lo que está hecho se guarda.',
  'Makes the graphics card\'s plan for every picture size of the handwriting reader now, for the quality chosen (about an hour the first time, once; another quality needs its own), so that no reading has to wait for one. Needs the "Graphics card" size of the handwriting model.': 'Hace ahora el plan de la tarjeta gráfica para cada tamaño de imagen del lector de escritura, para la calidad elegida (unas dos horas la primera vez, una sola vez; otra calidad necesita el suyo), para que ninguna lectura tenga que esperar. Necesita el tamaño «Tarjeta gráfica» del modelo de escritura a mano.',
  'Pad to fixed sizes': 'Rellenar hasta tamaños fijos',
  'Applies to models opened from now on; restart the app to switch all of them. Models that write text word by word always use the processor.': 'Se aplica a los modelos que se abran desde ahora; reinicia la aplicación para cambiarlos todos. Los modelos que escriben el texto palabra a palabra siempre usan el procesador.',
  'Graphics card runtime': 'Entorno de tarjeta gráfica',
  'Running now: {name} (ONNX Runtime {version})': 'En uso ahora: {name} (ONNX Runtime {version})',
  'the one in the app (processor only)': 'el de la aplicación (solo procesador)',
  'The one in the app (processor only)': 'El de la aplicación (solo procesador)',
  'The chosen runtime could not be opened: {why}': 'No se pudo abrir el entorno elegido: {why}',
  'No runtime with graphics card support found. Put one in this folder (see docs/gpu-runtime-packs.md): {folder}': 'No se encontró ningún entorno con soporte de tarjeta gráfica. Pon uno en esta carpeta (ver docs/gpu-runtime-packs.md): {folder}',
  'Takes effect when the app is started again. Folder of the runtimes: {folder}': 'Surte efecto al reiniciar la aplicación. Carpeta de los entornos: {folder}',
  'High refresh rate': 'Alta frecuencia de actualización',
  'Asks the screen for the fastest refresh rate it has (90 or 120 Hz on some devices): scrolling and drawing look smoother, and the battery lasts less. Android may still slow it down, for example in battery saver.': 'Pide a la pantalla su frecuencia de actualización más rápida (90 o 120 Hz en algunos dispositivos): el desplazamiento y el dibujo se ven más suaves, y la batería dura menos. Android puede seguir frenándolo, por ejemplo en el ahorro de batería.',
  'Turn it off when the battery is below': 'Desactivarlo cuando la batería esté por debajo de',
  'Never': 'Nunca',
  '{n} %': '{n} %',
  'Truth table': 'Tabla de verdad',
  'Type a formula: p -> q, !p | q, (p and q) or not r, or in LaTeX. Put = between two formulas to see whether they are the same.': 'Escribe una fórmula: p -> q, !p | q, (p y q) o no r, o en LaTeX. Pon = entre dos fórmulas para ver si son iguales.',
  'I cannot read that as a formula. Use single letters for the statements.': 'No puedo leer eso como fórmula. Usa letras sueltas para las proposiciones.',
  'That has too many letters (at most 10).': 'Tiene demasiadas letras (como máximo 10).',
  '0 first': 'Primero 0',
  '1 first': 'Primero 1',
  'Copy as Markdown': 'Copiar como Markdown',
  'Copy as LaTeX': 'Copiar como LaTeX',
  'Put on the page': 'Poner en la página',
  'Copied': 'Copiado',
  'Always true (a tautology)': 'Siempre verdadera (una tautología)',
  'Never true (a contradiction)': 'Nunca verdadera (una contradicción)',
  'Sometimes true': 'A veces verdadera',
  'The same in every row': 'Igual en cada fila',
  'Not the same: they differ in {n} of {total} rows': 'No son iguales: difieren en {n} de {total} filas',
  'The second follows from the first': 'La segunda se deduce de la primera',
  'The second does not follow from the first': 'La segunda no se deduce de la primera',
  'Other forms of the formula': 'Otras formas de la fórmula',
  'Of the first formula': 'De la primera fórmula',
  'True in rows': 'Verdadera en las filas',
  'False in rows': 'Falsa en las filas',
  'Shortest sum of products': 'Suma de productos más corta',
  'Shortest product of sums': 'Producto de sumas más corto',
  'Every true row as a product': 'Cada fila verdadera como producto',
  'Every false row as a sum': 'Cada fila falsa como suma',
  'none': 'ninguna',
  'none (it is never true)': 'ninguna (nunca es verdadera)',
  'none (it is always true)': 'ninguna (siempre es verdadera)',
  'Make the truth table of a formula': 'Hacer la tabla de verdad de una fórmula',
  'Outline or flowchart': 'Esquema o diagrama de flujo',
  'Automaton': 'Autómata',
  'Tree': 'Árbol',
  'Show an example': 'Mostrar un ejemplo',
  'One line for each arrow: q0 -a-> q1 (q0 --a,b--> q1 for two symbols, -eps-> for the empty word). Say where it starts and which states accept: start: q0, accept: q2 (or >q0 and *q2).': 'Una línea por flecha: q0 -a-> q1 (q0 --a,b--> q1 para dos símbolos, -eps-> para la palabra vacía). Indica dónde empieza y qué estados aceptan: start: q0, accept: q2 (o >q0 y *q2).',
  'Brackets: A(B(D,E),C), a gap for a missing child: 8(3,10(,14). Or numbers put into a search tree, bst: 8 3 10 1 (also avl:, minheap:, maxheap:, array: 1 3 2 4). Lines after that: insert 7, delete 3.': 'Paréntesis: A(B(D,E),C), un hueco para un hijo que falta: 8(3,10(,14). O números metidos en un árbol de búsqueda, bst: 8 3 10 1 (también avl:, minheap:, maxheap:, array: 1 3 2 4). Líneas siguientes: insert 7, delete 3.',
  'One line for each edge: A - B, an arrow A -> B, a weight A -3- B (or A - B : 3), a chain A - B - C. A node on its own gets a line of its own. start: A says where the searches begin.': 'Una línea por arista: A - B, una flecha A -> B, un peso A -3- B (o A - B : 3), una cadena A - B - C. Un nodo solo recibe una línea propia. start: A indica dónde empiezan las búsquedas.',
  'Show the balance factors': 'Mostrar los factores de equilibrio',
  'Line {n} is not understood: {text}': 'No se entiende la línea {n}: {text}',
  'Try a word': 'Probar una palabra',
  'accepted': 'aceptada',
  'rejected': 'rechazada',
  'stuck after {n} symbols': 'atascado tras {n} símbolos',
  'Make it deterministic': 'Hacerlo determinista',
  'Make it smallest': 'Hacerlo lo más pequeño posible',
  'Kind': 'Tipo',
  'States': 'Estados',
  'Alphabet': 'Alfabeto',
  'Complete': 'Completo',
  'Never reached': 'Nunca alcanzado',
  'Dead ends': 'Callejones sin salida',
  'Accepts': 'Acepta',
  'Nodes': 'Nodos',
  'Height': 'Altura',
  'Leaves': 'Hojas',
  'Search tree': 'Árbol de búsqueda',
  'Balanced (AVL)': 'Equilibrado (AVL)',
  'Min-heap': 'Montículo mínimo',
  'Max-heap': 'Montículo máximo',
  'Preorder': 'Preorden',
  'Inorder': 'Inorden',
  'Postorder': 'Postorden',
  'Level order': 'Por niveles',
  'Components': 'Componentes',
  'Has a cycle': 'Tiene un ciclo',
  'Bipartite': 'Bipartito',
  'Topological order': 'Orden topológico',
  'Strongly connected': 'Fuertemente conexo',
  'Degrees': 'Grados',
  'Breadth first': 'En anchura',
  'Depth first': 'En profundidad',
  'Shortest paths': 'Caminos más cortos',
  'Spanning tree': 'Árbol generador',
  'yes': 'sí',
  'no': 'no',
  'directed': 'dirigido',
  'undirected': 'no dirigido',
  'weighted': 'ponderado',
  'full': 'lleno',
  'complete': 'completo',
  'perfect': 'perfecto',
  'compared as text': 'comparados como texto',
  'DFA': 'AFD',
  'NFA': 'AFN',
  'NFA with ε moves': 'AFN con movimientos ε',
  'no (a missing arrow is a dead end)': 'no (una flecha que falta es un callejón sin salida)',
  'none (there is a cycle)': 'ninguno (hay un ciclo)',
  'not for negative weights': 'no para pesos negativos',
  'no start state (write start: q0 or >q0)': 'sin estado inicial (escribe start: q0 o >q0)',
  'no accepting state (write accept: q1 or *q1)': 'sin estado de aceptación (escribe accept: q1 o *q1)',
  'a bracket is not closed': 'un paréntesis no está cerrado',
  'a node has no name before "("': 'un nodo no tiene nombre antes de «(»',
  'the first place is the root, it cannot be a hole': 'el primer lugar es la raíz, no puede ser un hueco',
  'Connect temporarily': 'Conectar temporalmente',
  'Fetching the note from your other device...': 'Trayendo la nota desde tu otro dispositivo...',
  'The note could not be fetched. Is the device that has it online?': 'No se pudo traer la nota. ¿Está en línea el dispositivo que la tiene?',
  'Scan the code of the web version': 'Escanear el código de la versión web',
  'On a computer that is not yours: "Connect temporarily" shows a code that you scan with your phone. Your notes are listed here, and each one comes when you open it. This browser forgets them again when the tab is closed.': 'En un ordenador que no es tuyo: «Conectar temporalmente» muestra un código que escaneas con el teléfono. Tus notas aparecen aquí, y cada una llega al abrirla. Este navegador las olvida de nuevo al cerrar la pestaña.',
  'This browser is connected temporarily. There are changes that no other device has yet: they are lost if you close the tab before the next sync.': 'Este navegador está conectado temporalmente. Hay cambios que ningún otro dispositivo tiene todavía: se perderán si cierras la pestaña antes de la próxima sincronización.',
  'This browser is connected temporarily. Everything here is on your other devices; it is forgotten when you sign out or close the tab.': 'Este navegador está conectado temporalmente. Todo lo que hay aquí está en tus otros dispositivos; se olvida al cerrar sesión o la pestaña.',
  'Sign out and forget everything here': 'Cerrar sesión y olvidar todo aquí',
  'Sign out of this browser?': '¿Cerrar sesión en este navegador?',
  'This browser forgets the notes and the profile. No other device is connected, so notes that are only here are lost.': 'Este navegador olvida las notas y el perfil. Ningún otro dispositivo está conectado, así que las notas que solo están aquí se perderán.',
  'There are changes here that no other device has yet. They are lost when you sign out. Press "Sync now" first and wait until it is done to keep them. This browser forgets the notes and the profile either way.': 'Hay cambios aquí que ningún otro dispositivo tiene todavía. Se pierden al cerrar sesión. Pulsa primero «Sincronizar ahora» y espera a que termine para conservarlos. De todos modos, este navegador olvida las notas y el perfil.',
  'This browser forgets the notes and the profile. Your other devices keep everything.': 'Este navegador olvida las notas y el perfil. Tus otros dispositivos conservan todo.',
  'Scan this code with your phone: with the camera, or in Notation under Settings → Sync profile → "Scan the code of the web version".': 'Escanea este código con tu teléfono: con la cámara, o en Notation en Ajustes → Perfil de sincronización → «Escanear el código de la versión web».',
  'Waiting for your phone...': 'Esperando a tu teléfono...',
  'This browser is signed in until you sign out or close the tab, and then forgets your notes. The code works for ten minutes and only once; your phone still asks you before it lets this browser in.': 'Este navegador queda con sesión iniciada hasta que cierres sesión o la pestaña, y luego olvida tus notas. El código funciona diez minutos y solo una vez; tu teléfono sigue pidiendo permiso antes de dejar entrar a este navegador.',
  'Point the camera at the code that the web version shows.': 'Apunta la cámara al código que muestra la versión web.',
  'temporary': 'temporal',
  'Sign in with your cloud folder': 'Iniciar sesión con tu carpeta en la nube',
  'signed in with the recovery key': 'sesión iniciada con la clave de recuperación',
  'Your recovery key': 'Tu clave de recuperación',
  'Keep it in a password manager or write it on paper. It is shown only now and the app does not keep it. With this key and your cloud account you can sign in to your profile on a new device; without it, only a link from one of your devices works.': 'Guárdala en un gestor de contraseñas o escríbela en papel. Solo se muestra ahora y la aplicación no la guarda. Con esta clave y tu cuenta en la nube puedes iniciar sesión en tu perfil en un dispositivo nuevo; sin ella, solo funciona un enlace desde uno de tus dispositivos.',
  'I have saved the key': 'He guardado la clave',
  'Use the folder your other devices sync through, and the recovery key that was shown when signing in was turned on there. Your notes, folders and settings come to this device.': 'Usa la carpeta por la que sincronizan tus otros dispositivos, y la clave de recuperación que se mostró al iniciar sesión se activó allí. Tus notas, carpetas y ajustes llegan a este dispositivo.',
  '{service} is connected.': '{service} está conectado.',
  'Connect your account first:': 'Conecta primero tu cuenta:',
  'In a browser, your Nextcloud has to allow this website to talk to it (CORS headers); the documentation says which.': 'En un navegador, tu Nextcloud tiene que permitir que este sitio hable con él (cabeceras CORS); la documentación dice cuáles.',
  'Recovery key': 'Clave de recuperación',
  '"Sign out" in the menu removes everything from this browser again.': '«Cerrar sesión» en el menú vuelve a quitar todo de este navegador.',
  'Sign in': 'Iniciar sesión',
  'Sign in with this folder?': '¿Iniciar sesión con esta carpeta?',
  'Anyone who has the recovery key and can open this cloud folder will be able to sign in to your profile and read your notes, without anyone saying yes on one of your other devices. Your devices show each device that signs in this way, and you can take it out. The key is shown once and not kept by the app. Adding a device with a link works as before.': 'Cualquiera que tenga la clave de recuperación y pueda abrir esta carpeta en la nube podrá iniciar sesión en tu perfil y leer tus notas, sin que nadie diga sí en uno de tus otros dispositivos. Tus dispositivos muestran cada dispositivo que entra así, y puedes quitarlo. La clave se muestra una sola vez y la aplicación no la guarda. Añadir un dispositivo con un enlace funciona como antes.',
  'Turn on': 'Activar',
  'Turn off signing in with the folder?': '¿Desactivar el inicio de sesión con la carpeta?',
  'The sign-in file is taken out of the folder, so the recovery key stops working. Devices that are already in stay in.': 'El archivo de inicio de sesión se quita de la carpeta, así que la clave de recuperación deja de funcionar. Los dispositivos que ya están dentro se quedan.',
  'Turn off': 'Desactivar',
  'Make a new recovery key?': '¿Crear una clave de recuperación nueva?',
  'The old key stops working at once. Devices that signed in with it stay in; to cut one off, take it out of the list of devices.': 'La clave antigua deja de funcionar de inmediato. Los dispositivos que entraron con ella se quedan; para cortar uno, quítalo de la lista de dispositivos.',
  'Make a new key': 'Crear una clave nueva',
  'Let me sign in with this folder': 'Permitirme iniciar sesión con esta carpeta',
  'On a new device or in a browser, sign in with this cloud account and a recovery key instead of a link and a yes on another device. Off by default: adding a device with a link stays the careful way.': 'En un dispositivo nuevo o en un navegador, inicia sesión con esta cuenta en la nube y una clave de recuperación en lugar de un enlace y un sí en otro dispositivo. Desactivado por defecto: añadir un dispositivo con un enlace sigue siendo la forma prudente.',
  'Needs the sync through the folder to be on, with the account connected on this device.': 'Necesita que la sincronización por carpeta esté activada, con la cuenta conectada en este dispositivo.',
  'Make a new recovery key': 'Crear una clave de recuperación nueva',
  'Signed in with the recovery key: {devices}': 'Sesión iniciada con la clave de recuperación: {devices}',
  'This device is part of a profile already. Leave it first to sign in to another.': 'Este dispositivo ya forma parte de un perfil. Sal primero para iniciar sesión en otro.',
  'Connect the account of {service} first.': 'Conecta primero la cuenta de {service}.',
  'That recovery key does not open this folder. Check it for typing mistakes, and that it is the latest one if you made a new key.': 'Esa clave de recuperación no abre esta carpeta. Revísala por si hay errores de escritura, y que sea la última si creaste una clave nueva.',
  'The sign-in file in the folder cannot be read.': 'El archivo de inicio de sesión de la carpeta no se puede leer.',
  'The sign-in file in the folder is from a newer version of the app: update the app.': 'El archivo de inicio de sesión de la carpeta es de una versión más nueva de la aplicación: actualiza la aplicación.',
  'Signing in needs the sync through a cloud folder to be on, with the account connected on this device.': 'Iniciar sesión necesita que la sincronización por carpeta en la nube esté activada, con la cuenta conectada en este dispositivo.',
  'Signing in is not on.': 'El inicio de sesión no está activado.',
  'That is not a recovery key. It has 25 letters and digits, like ABCDE-FGHJK-MNPQR-STUVW-XY234.': 'Eso no es una clave de recuperación. Tiene 25 letras y cifras, como ABCDE-FGHJK-MNPQR-STUVW-XY234.',
  'Nothing to sign in to was found in this folder. Is signing in turned on on your other device, and is the folder name the same?': 'No se encontró nada a lo que iniciar sesión en esta carpeta. ¿Está activado el inicio de sesión en tu otro dispositivo, y el nombre de la carpeta es el mismo?',
  'Enter the address of your Nextcloud first.': 'Introduce primero la dirección de tu Nextcloud.',
  'Waiting for you to approve in the browser...': 'Esperando que lo apruebes en el navegador...',
  'Log in with the browser': 'Iniciar sesión con el navegador',
  'The browser could not be opened. Open this address yourself:': 'No se pudo abrir el navegador. Abre tú esta dirección:',
  'Or enter an app password yourself:': 'O introduce tú una contraseña de aplicación:',
  'That is not a server address.': 'Eso no es una dirección de servidor.',
  'This server did not start a login. Is it a Nextcloud (version 16 or newer), and is the address right?': 'Este servidor no inició un inicio de sesión. ¿Es un Nextcloud (versión 16 o posterior), y la dirección es correcta?',
  'The server did not hand over a login.': 'El servidor no entregó ningún inicio de sesión.',
  'The login was not approved in time. Try again.': 'El inicio de sesión no se aprobó a tiempo. Inténtalo de nuevo.',
  'The server could not be reached: {error}': 'No se pudo contactar con el servidor: {error}',
  'The password of the Nextcloud account is not in the keystore of this device. Log in again in the settings under Sync and sharing.': 'La contraseña de la cuenta de Nextcloud no está en el almacén de claves de este dispositivo. Vuelve a iniciar sesión en los ajustes, en Sincronización y uso compartido.',
  'The password of this account is not in the keystore of this device. Log in again.': 'La contraseña de esta cuenta no está en el almacén de claves de este dispositivo. Vuelve a iniciar sesión.',
  'Choose calendars': 'Elegir calendarios',
  'The system keystore did not keep the password, so the account was not saved. Is the keyring unlocked?': 'El almacén de claves del sistema no guardó la contraseña, así que la cuenta no se guardó. ¿Está desbloqueado el llavero?',
  'Eyedropper': 'Cuentagotas',
  'Pick a color from anything on the page (a drawing, a picture, a PDF) for the pen: tap the button or press I, then touch the color.': 'Toma un color de cualquier cosa de la página (un dibujo, una imagen, un PDF) para el lápiz: pulsa el botón o pulsa I, y luego toca el color.',
  'Eyedropper: touch anything on the page to draw in its color (I)': 'Cuentagotas: toca cualquier cosa de la página para dibujar con su color (I)',
  'Free transform': 'Transformación libre',
  'Bend selected drawings: distort them by the corners, give them perspective, skew them, turn them by any angle or warp them with a net. The whole change is one step to take back.': 'Deformar los dibujos seleccionados: estirarlos por las esquinas, darles perspectiva, inclinarlos, girarlos en cualquier ángulo o deformarlos con una malla. Todo el cambio es un solo paso para deshacer.',
  'Transform: distort, perspective, skew, rotate, warp': 'Transformar: deformar, perspectiva, inclinar, girar, combar',
  'Distort: pull the corners anywhere': 'Deformar: tirar de las esquinas a cualquier sitio',
  'Perspective: pull a corner, the next one follows': 'Perspectiva: tirar de una esquina, la siguiente la sigue',
  'Skew: slide the edges': 'Inclinar: deslizar los bordes',
  'Rotate (Shift: in steps of 15°)': 'Girar (Mayús: en pasos de 15°)',
  'Warp: bend the drawing with a net': 'Combar: doblar el dibujo con una malla',
  'Start again': 'Empezar de nuevo',
  'Fill bucket': 'Cubo de relleno',
  'Fill a closed area of a drawing with the pen color by touching it: the area is found from the lines round it, and small gaps in them can be closed. The fill is a shape under the lines, so it can be recolored or moved later.': 'Rellenar un área cerrada de un dibujo con el color del lápiz tocándola: el área se encuentra a partir de las líneas que la rodean, y se pueden cerrar pequeños huecos en ellas. El relleno es una forma bajo las líneas, así que luego se puede recolorear o mover.',
  'Fill bucket: touch a closed area to fill it with the pen color (G)': 'Cubo de relleno: toca un área cerrada para rellenarla con el color del lápiz (G)',
  'Gap closing: how big a gap in the lines still closes an area': 'Cierre de huecos: cuánto puede ser un hueco en las líneas y aun así cerrar un área',
  'No gap closing': 'Sin cierre de huecos',
  'Small gaps': 'Huecos pequeños',
  'Medium gaps': 'Huecos medianos',
  'Large gaps': 'Huecos grandes',
  'There are no lines to close an area yet: draw the outline first.': 'Todavía no hay líneas que cierren un área: dibuja primero el contorno.',
  'That area is not closed. Close the lines, or turn gap closing up (the button beside the bucket).': 'Esa área no está cerrada. Cierra las líneas, o sube el cierre de huecos (el botón junto al cubo).',
  'That is on a line: touch the area beside it.': 'Eso está sobre una línea: toca el área al lado.',
  'Turn the canvas left': 'Girar el lienzo a la izquierda',
  'Turn the canvas right': 'Girar el lienzo a la derecha',
  'Put the canvas straight': 'Enderezar el lienzo',
  'The canvas is turned: tap to put it straight': 'El lienzo está girado: toca para enderezarlo',
  'Bring your notes from another app': 'Traer tus notas desde otra aplicación',
  'Obsidian: a vault folder': 'Obsidian: una carpeta de bóveda',
  'Notes, folders, pictures, PDFs and tags are taken; links between notes keep working.': 'Se toman notas, carpetas, imágenes, PDF y etiquetas; los enlaces entre notas siguen funcionando.',
  'Obsidian: a vault as a zip': 'Obsidian: una bóveda en zip',
  'The same, from a zip of the vault folder.': 'Lo mismo, desde un zip de la carpeta de la bóveda.',
  'Notion: an export': 'Notion: una exportación',
  'In Notion: Settings, Export all workspace content, Markdown & CSV. Pick the zip you get.': 'En Notion: Ajustes, Exportar todo el contenido del espacio de trabajo, Markdown y CSV. Elige el zip que obtienes.',
  'GoodNotes: PDFs or a .goodnotes file': 'GoodNotes: PDF o un archivo .goodnotes',
  'In GoodNotes: Share, Export as PDF. Handwriting stays as it looks. A .goodnotes file can only give its PDFs.': 'En GoodNotes: Compartir, Exportar como PDF. La escritura a mano se conserva tal como se ve. Un archivo .goodnotes solo puede dar sus PDF.',
  'Reading your notes...': 'Leyendo tus notas...',
  'Pick the vault folder': 'Elige la carpeta de la bóveda',
  'Pick the Notion export (zip)': 'Elige la exportación de Notion (zip)',
  'Pick the vault (zip)': 'Elige la bóveda (zip)',
  'Pick the PDFs or the .goodnotes files': 'Elige los PDF o los archivos .goodnotes',
  'What is written by hand in "{name}" is in a format that cannot be read. Only its PDF pages were taken; to keep the handwriting, export the notebook as a PDF in GoodNotes.': 'La escritura a mano de «{name}» está en un formato que no se puede leer. Solo se tomaron sus páginas PDF; para conservar la escritura, exporta el cuaderno como PDF desde GoodNotes.',
  'Could not read the notes: {error}': 'No se pudieron leer las notas: {error}',
  'Nothing was taken in': 'No se tomó nada',
  'Your notes are here': 'Tus notas están aquí',
  '{n} PDF': '{n} PDF',
  '{n} PDFs': '{n} PDF',
  '{n} table (a database)': '{n} tabla (una base de datos)',
  '{n} tables (databases)': '{n} tablas (bases de datos)',
  '{n} picture': '{n} imagen',
  '{n} folder': '{n} carpeta',
  '{n} folders': '{n} carpetas',
  '{n} link between notes kept': '{n} enlace entre notas conservado',
  '{n} links between notes kept': '{n} enlaces entre notas conservados',
  'Could not be read': 'No se pudo leer',
  'Left out (not notes or pictures)': 'Dejado fuera (no son notas ni imágenes)',
  'Links to something that was not there (kept as plain text)': 'Enlaces a algo que no estaba (conservados como texto sin formato)',
  'Open a note': 'Abrir una nota',
  'This is not a zip file.': 'Esto no es un archivo zip.',
  'This is not a GoodNotes file. In GoodNotes, choose Share → Export as PDF and open that PDF here.': 'Esto no es un archivo de GoodNotes. En GoodNotes, elige Compartir → Exportar como PDF, y abre ese PDF aquí.',
  'There is no PDF in this GoodNotes file, and what is written in it cannot be read. In GoodNotes, choose Share → Export as PDF and open that PDF here.': 'No hay ningún PDF en este archivo de GoodNotes, y lo escrito en él no se puede leer. En GoodNotes, elige Compartir → Exportar como PDF, y abre ese PDF aquí.',
  'The archive has too many files.': 'El archivo tiene demasiados ficheros.',
  'A file in the archive is too big.': 'Un fichero del archivo es demasiado grande.',
  'The archive is too big.': 'El archivo es demasiado grande.',
  'A to-do line is found in a note': 'Se encuentra una línea pendiente en una nota',
  'A note is left alone for a moment after changes': 'Una nota se deja tranquila un momento tras los cambios',
  'A page is added to a note': 'Se añade una página a una nota',
  'Something is highlighted in a note': 'Algo se resalta en una nota',
  'A note is linked to another note': 'Una nota se enlaza con otra nota',
  'A PDF is imported': 'Se importa un PDF',
  'A recording is kept with a note': 'Se guarda una grabación con una nota',
  'A task is done': 'Una tarea se completa',
