  'A meeting with a note of its own is over': 'Termina una reunión con nota propia',
  'Something is kept from the web or shared to the app': 'Se guarda algo de la web o se comparte con la aplicación',
  'You press a trigger (a shortcut or the pen button)': 'Pulsas un disparador (un atajo o el botón del lápiz)',
  'how many pages the note has now': 'cuántas páginas tiene la nota ahora',
  'how many highlights were added': 'cuántos resaltados se añadieron',
  'the title of the note it links to': 'el título de la nota enlazada',
  'the file name of the PDF': 'el nombre de archivo del PDF',
  'the title of the recording': 'el título de la grabación',
  'how long it is, in minutes': 'cuánto dura, en minutos',
