  'Add a translation of the note as a text box (the assistant writes it)': 'Añadir una traducción de la nota como cuadro de texto (la escribe el asistente)',
  'Add a summary of the note as a text box (the assistant writes it)': 'Añadir un resumen de la nota como cuadro de texto (lo escribe el asistente)',
