  'Make a new note from a template': 'Crear una nota nueva a partir de una plantilla',
  'Prepare a note for the meeting (with what was left open last time)': 'Preparar una nota para la reunión (con lo que quedó abierto la vez anterior)',
  'Set a reminder': 'Poner un recordatorio',
  'Save the pages of the note as pictures (PNG) into a folder': 'Guardar las páginas de la nota como imágenes (PNG) en una carpeta',
  'Add the web page it came from to the sources (citations)': 'Añadir la página web de la que viene a las fuentes (citas)',
  'Ask me what to do about the note (a card on the dashboard)': 'Preguntarme qué hacer con la nota (una tarjeta en el panel)',
  'Give a note without a title one, from what it says': 'Dar a una nota sin título uno a partir de lo que dice',
  'Make flashcards from the note (the assistant writes them)': 'Crear tarjetas de estudio a partir de la nota (las escribe el asistente)',
  'Add a task when flashcards are due for review': 'Añadir una tarea cuando haya tarjetas de estudio que repasar',
  'Add it to': 'Añadirlo a',
  'The note the rule is about': 'La nota a la que se refiere la regla',
  'A daily note (made if it is not there)': 'Una nota diaria (se crea si no existe)',
  'Title of the daily note': 'Título de la nota diaria',
  'Folder for a new daily note': 'Carpeta para una nota diaria nueva',
  'Text to add': 'Texto que añadir',
  'It goes in a box under the rest of the last page': 'Va en un cuadro bajo el resto de la última página',
  'Tag': 'Etiqueta',
  'A tag of the tag tree, e.g. school/maths; the words in braces of the event can be used: reading/{kind}': 'Una etiqueta del árbol de etiquetas, p. ej. colegio/mates; se pueden usar las palabras entre llaves del evento: lectura/{kind}',
  'Title of the note': 'Título de la nota',
  '{title} is the title of the event; {date} today': '{title} es el título del evento; {date} la fecha de hoy',
  'Template (optional)': 'Plantilla (opcional)',
  '{title} is the name of the event, {day} its day, {start} its time': '{title} es el nombre del evento, {day} su día, {start} su hora',
  'Bring along what is still open from the last meeting': 'Traer lo que sigue abierto de la última reunión',
  'Yes: the to-do lines of the last note of that name': 'Sí: las líneas pendientes de la última nota de ese nombre',
  'This evening (18:00)': 'Esta tarde (18:00)',
  'Tomorrow morning (9:00)': 'Mañana por la mañana (9:00)',
  'In a week (9:00)': 'Dentro de una semana (9:00)',
  'Save the pictures in this folder': 'Guardar las imágenes en esta carpeta',
  'the note\'s': 'de la nota',
  '{title} is empty, {date} today\'s date': '{title} está vacío, {date} la fecha de hoy',
  '{title} is the event\'s title, {date} today\'s date': '{title} es el título del evento, {date} la fecha de hoy',
  '{summary} is what is to be done, {line} the whole line, {title} the note\'s title. The task is on the day the line says ("by Friday"), else on the day below': '{summary} es lo que hay que hacer, {line} la línea completa, {title} el título de la nota. La tarea va en el día que dice la línea («antes del viernes»), si no, en el día de abajo',
  'The page the note was made from (its address, its title, the site and the day it was kept) is added to the sources of the citations, to cite in any note with [@key]. A page that is a source already is not added again.': 'La página de la que procede la nota (su dirección, su título, el sitio y el día en que se guardó) se añade a las fuentes de las citas, para citarla en cualquier nota con [@clave]. Una página que ya es una fuente no se vuelve a añadir.',
  'The note is listed on the dashboard: "Still relevant?" with the answers: keep it, archive it, remind me in a week, make flashcards of it, or not now. Nothing changes until you answer.': 'La nota aparece en el panel: «¿Sigue siendo relevante?» con las respuestas: conservarla, archivarla, recordármelo en una semana, hacer tarjetas de estudio de ella, o ahora no. No cambia nada hasta que respondas.',
  'The note is starred, so that it is listed as a favourite on the dashboard.': 'La nota recibe una estrella, para que aparezca como favorita en el panel.',
  'The assistant reads the text of the note and writes its outline (topics and points) into a text box under the rest of the last page. A later run replaces it. Needs the assistant.': 'El asistente lee el texto de la nota y escribe su esquema (temas y puntos) en un cuadro de texto debajo del resto de la última página. Una ejecución posterior lo reemplaza. Necesita el asistente.',
  'The assistant reads the text of the note and writes a short summary into a text box under the rest of the last page. A later run replaces it. Needs the assistant.': 'El asistente lee el texto de la nota y escribe un resumen breve en un cuadro de texto debajo del resto de la última página. Una ejecución posterior lo reemplaza. Necesita el asistente.',
