  'Often': 'A menudo',
  'When the model is unsure of a formula, it reads it again with a thinner and a thicker pen and keeps the surest reading. Normal does this for about one formula in ten and reads about 2 points more right; Often is about three in ten; Never is the quickest.': 'Cuando el modelo duda de una fórmula, la vuelve a leer con un lápiz más fino y otro más grueso, y se queda con la lectura más segura. Normal hace esto en unas una de cada diez fórmulas y acierta unos 2 puntos más; A menudo, unas tres de cada diez; Nunca es lo más rápido.',
  'The reader was not sure of this word': 'El lector no estaba seguro de esta palabra',
