  'Copy formatting, then select text and press again to apply it': 'Copiar el formato, luego selecciona el texto y pulsa de nuevo para aplicarlo',
  'A title, an introduction, the main part and a conclusion, the sources at the end': 'Un título, una introducción, la parte principal y una conclusión, las fuentes al final',
  'Every paragraph of a kind takes its look; what is picked for single words stays.': 'Cada párrafo de un tipo toma su aspecto; lo que se elige para palabras sueltas se mantiene.',
  'Read from your drawing: {nodes} circles, {edges} lines. Check the names, then put it on the page; your drawing is replaced.': 'Leído de tu dibujo: {nodes} círculos, {edges} líneas. Revisa los nombres y luego colócalo en la página; tu dibujo se reemplaza.',
  'This package was exported in the newest Anki format. Export it again with "Support older Anki versions" ticked.': 'Este paquete se exportó en el formato más reciente de Anki. Expórtalo de nuevo marcando «Admitir versiones antiguas de Anki».',
  '{page} is the number of the page, {pages} how many there are, {title} the title of the note, {date} today.': '{page} es el número de la página, {pages} cuántas hay, {title} el título de la nota, {date} la fecha de hoy.',
  'Remove this PDF?': '¿Quitar este PDF?',
  '"{name}" and its pages are taken out of the note, with what is drawn or written on them.': '«{name}» y sus páginas se quitan de la nota, con lo que está dibujado o escrito en ellas.',
  'The PDFs of this note': 'Los PDF de esta nota',
  '{n} pages': '{n} páginas',
  'Remove {name}…': 'Quitar {name}…',
  '{n} PDFs ({pages} Pages)': '{n} PDF ({pages} páginas)',
  'The pages of the PDFs in the file do not fit them; the note is opened without them': 'Las páginas de los PDF del archivo no les corresponden; la nota se abre sin ellas',
  'A PDF in the file does not match its checksum and was left out': 'Un PDF del archivo no coincide con su suma de comprobación y se omitió',
  'You are on mobile data. These models are large: untick them to download later on Wi-Fi (the settings have the same list), or go ahead if your plan allows it.': 'Estás con datos móviles. Estos modelos son grandes: desmárcalos para descargarlos después con Wi-Fi (los ajustes tienen la misma lista), o continúa si tu tarifa lo permite.',
  'Export the whole note as Markdown': 'Exportar la nota completa como Markdown',
  'Export as Markdown': 'Exportar como Markdown',
  'Handwriting is in it as read by the app: check it. Drawings are not in it.': 'La escritura a mano aparece tal como la leyó la aplicación: revísala. Los dibujos no aparecen.',
  'Syncs by itself whenever two of your devices are online at the same time. This needs the signalling server: the device stays connected to it, which tells it that a device of yours is online (it cannot tell which, or what is in your notes). Off: only when you press "Sync now".': 'Se sincroniza solo siempre que dos de tus dispositivos estén en línea a la vez. Esto necesita el servidor de señalización: el dispositivo permanece conectado a él, lo que le indica que uno de tus dispositivos está en línea (no puede saber cuál, ni qué hay en tus notas). Desactivado: solo cuando pulsas «Sincronizar ahora».',
  'For devices that are not online at the same time: each puts what changed in a folder on your cloud storage and takes in what the others put there, without the signalling server. Two things still need it: handing the cloud accounts to your other devices (when two of them sync directly; or connect the account on each device yourself), and working on one note on two devices at the same time.': 'Para dispositivos que no están en línea a la vez: cada uno deja lo que cambió en una carpeta de tu almacenamiento en la nube y toma lo que los demás dejaron allí, sin el servidor de señalización. Dos cosas aún lo necesitan: entregar las cuentas de nube a tus otros dispositivos (cuando dos de ellos se sincronizan directamente; o conectar la cuenta en cada dispositivo tú mismo), y trabajar en una misma nota desde dos dispositivos a la vez.',
  'A file in the folder is not sealed with the key of this profile; it was not taken.': 'Un archivo de la carpeta no está cifrado con la clave de este perfil; no se tomó.',
  'Your notes are also kept in sync through the cloud folder below, also when your devices are not online at the same time.': 'Tus notas también se sincronizan a través de la carpeta en la nube de abajo, incluso cuando tus dispositivos no están en línea a la vez.',
  'While a note is open, this device is connected to the signalling server and tells your other devices which notes are open; a note that is open on two of them is edited together live. What it tells them is encrypted: the server cannot see which note it is, nor that the same note is opened again. Off: the server hears nothing from this device while a note is open, and a note changed on two devices is brought together at the next sync.': 'Mientras una nota está abierta, este dispositivo está conectado al servidor de señalización y le indica qué notas están abiertas; una nota abierta en dos de tus dispositivos se edita en conjunto en vivo. Lo que les transmite va cifrado: el servidor no puede ver de qué nota se trata, ni que la misma nota se vuelve a abrir. Desactivado: el servidor no oye nada de este dispositivo mientras una nota está abierta, y una nota cambiada en dos dispositivos se une en la siguiente sincronización.',
  'Handwriting: {done} of {all} picture sizes of this quality have their plan. Missing: {missing} (widths in columns of 28 pixels). Plans made before this was noted are found again by "Precompile picture sizes", in seconds each.': 'Escritura a mano: {done} de {all} tamaños de imagen de esta calidad tienen su plan. Faltan: {missing} (anchos en columnas de 28 píxeles). Los planes hechos antes de que esto se anotara se vuelven a encontrar con «Precompilar los tamaños de imagen», en segundos cada uno.',
  'Models run on the processor now, so Exact is used: it reads the same there, as fast, with about 1 GB less memory. The graphics card file is kept for when the card is used again.': 'Los modelos ahora se ejecutan en el procesador, así que se usa Exacto: lee igual allí, igual de rápido, con unos 1 GB menos de memoria. El archivo de la tarjeta gráfica se conserva para cuando se vuelva a usar la tarjeta.',
  'the graphics card is making its plan for this picture size (minutes, once); the processor reads meanwhile': 'la tarjeta gráfica está haciendo su plan para este tamaño de imagen (minutos, una sola vez); mientras tanto el procesador lee',
  'Always on with CoreML for the "Graphics card" size of the handwriting model: CoreML prepares it once for each picture width (seconds, kept for the next start), so pictures are made one of a few widths.': 'Siempre activo con CoreML para el tamaño «Tarjeta gráfica» del modelo de escritura a mano: CoreML lo prepara una vez para cada ancho de imagen (segundos, guardado para el siguiente inicio), así que las imágenes se hacen en unos pocos anchos.',
  'Needed with this accelerator: it works out a plan for every picture size it sees, which takes minutes. Pictures of handwriting are made one of a few widths (about a fifth more work) so each plan is made once.': 'Necesario con este acelerador: calcula un plan para cada tamaño de imagen que ve, lo que tarda minutos. Las imágenes de escritura se hacen en unos pocos anchos (alrededor de una quinta parte más de trabajo), para que cada plan se haga una sola vez.',
  'Makes pictures of handwriting one of a few widths, so an accelerator that works out a plan for each size (AMD) does it a few times, not for every line. Costs about a fifth more work; switch it off where the accelerator takes any size.': 'Hace que las imágenes de escritura tengan uno de unos pocos anchos, de modo que un acelerador que calcula un plan para cada tamaño (AMD) lo hace unas pocas veces, y no para cada línea. Cuesta alrededor de una quinta parte más de trabajo; desactívalo donde el acelerador acepte cualquier tamaño.',
  'Line and shape correction': 'Corrección de líneas y formas',
  'How close to straight a line, or to a rectangle, ellipse, triangle or diamond a drawing, must be before it is corrected. Applies to notes opened after the change.': 'Cuánto debe acercarse una línea a una recta, o un dibujo a un rectángulo, una elipse, un triángulo o un rombo, antes de corregirse. Se aplica a las notas abiertas después del cambio.',
  'Only neat drawings': 'Solo dibujos limpios',
  'Rough drawings too': 'También dibujos aproximados',
