  'Say what the exam is, when it is and what to study for it. The app cuts the material into parts, finds free times in your calendar and shows you the sessions. Nothing goes in your calendar until you approve it.': 'Di qué examen es, cuándo es y qué tienes que estudiar. La aplicación divide el material en partes, busca huecos libres en tu calendario y te muestra las sesiones. Nada se añade a tu calendario hasta que lo apruebes.',
